programs.sol:
"""A local delimiter-reopening signal.

Quote and markup marks receive negative values when they follow their closing
mark, allowing intervening whitespace. Line breaks, indentation, and whether
the mark is a whole token control the strength. Repeated middle dots are
positive; a colon after the heading 'Title' is negative. Other tokens are
nearly zero. Only the last four tokens of the current document are retained.
"""
READS = ()

MATES = {
    '"': '"', "'": "'", '“': '”', '”': '”', '„': '”',
    '`': '`', '[': ']', '*': '*', '|': '|', '$': '$',
    '\\': '\\', '^': '^', '‘': '’', '’': '’', '‚': '’',
    '「': '」', '」': '」', '『': '』', '』': '』', '·': '·',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else []
    s = prefix.token_strings[-1]
    mark = s.lstrip()
    previous = history[-1] if history else ''
    before = ''.join(history)
    new_carry = (doc, (history + [s])[-4:])
    mate = '*/' if mark.startswith('/*') else MATES.get(mark[:1])

    value = 0.0013
    if mark == ':' and previous == 'Title':
        value = -2.184
    elif mate and before.rstrip().endswith(mate):
        line_start = '\n' in before and not before.rsplit('\n', 1)[-1].strip()
        if previous.endswith(('\n', '\r')):
            if s != mark:
                value = -0.0205
            elif mark.startswith('|'):
                value = -1.6704
            elif mark.startswith('/*'):
                value = -4.0384
            else:
                value = -2.754
        elif mark.startswith('·'):
            value = 1.3742
        elif mark == mate:
            if mark == '`':
                value = -1.5351 if len(previous) <= 1 else -2.9519
            elif mark == '"':
                value = -1.6052
            else:
                value = -0.0912
        elif line_start:
            value = -0.4442 if len(previous) <= 2 else -5.6256
        elif mark.startswith('$'):
            value = -2.338 if mark.startswith('$$') else -0.0575
        else:
            value = -0.035
    return new_carry, value

"""Approximate a detector for r-bearing spellings, not general sentiment.

Thrive and flourish are strongest; several other English rhotic stems and
short syllables split across tokens give smaller positive responses.  Some
Cyrillic sh/r continuations instead get negative values.  Only the trailing
word and previous token are remembered, and documents reset both.
"""
import re

READS = ()
ROOTS = {
    'flourish': 6.0,
    'nourish': 3.1,
    'cherish': 2.8,
    'striv': 3.3,
    'surviv': 0.77,
    'reviv': 1.8,
    'shiv': 5.4,
    'thril': 1.6,
    'thrif': 2.0,
    'thron': 1.1,
    'treasur': 0.43,
    'shore': 0.71,
    'shine': 0.80,
    'stirr': 0.71,
    'rish': 0.55,
}
TAIL = re.compile(r'[a-zа-яё]+$')


def response(s, old, previous, word):
    def new(root):
        return root in word and root not in old

    if new('thriv'):
        return 9.1 if word.endswith(('thrive', 'thrives')) else 5.1
    if new('struggl'):
        return 1.4 if word.endswith('struggle') else 2.3
    for root, strength in ROOTS.items():
        if new(root):
            return strength
    if new('flour'):
        return 6.5 if s.startswith('our') else 2.2
    if word.lstrip().startswith('shr') and new('shr'):
        return 3.1 if word.lstrip().startswith('shrine') else 1.1
    if old == 'shr' and s[:1] in 'aeiou':
        return 0.88
    if word.lstrip() == 'thr':
        return 3.4

    # Letter clusters crossing the token boundary.
    if previous.endswith('ш'):
        if s.startswith('ру'):
            return -6.5
        if s.startswith('ар'):
            return -3.1
    if previous.endswith('ch'):
        if s == 'ur':
            return -2.8
        if s.startswith('or'):
            return -0.35
    if s.startswith('iv'):
        if previous.endswith(('tr', 'ev')):
            return 2.7
        if previous.endswith('cr'):
            return 1.6
        if previous.endswith(('r', 'v')):
            return 0.6
    if previous.endswith('tr') and s.startswith(('ich', 'im')):
        return 1.7
    if previous.endswith(('th', 'sh')):
        if s.startswith('r') and len(s) <= 4:
            return 1.4
        if s.startswith(('ir', 'ur', 'im')):
            return 0.75
    if previous.endswith('ri') and s.startswith('ure'):
        return 4.5
    if s.startswith('ure'):
        return 0.20
    if previous.endswith('tr') and s.startswith(('i', 'u')):
        return 0.28
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    old, previous = ('', '') if initial else carry[1:]
    s = prefix.token_strings[-1].lower()
    if not s or not s[0].isalpha():
        old, previous = '', ''
    word = old + s
    value = response(s, old, previous, word)
    if initial and value == 0.0:
        value = -0.14
    match = TAIL.search(word)
    tail = match.group()[-30:] if match else ''
    return (doc, tail, s), value

"""A coarse detector of stranded or interrupted English word endings.

Compare a spelling's frequency as the end of a longer dictionary word with
its frequency as a whole word. Also try joining words split by whitespace
or a hyphen: a much more familiar joined spelling gets a larger response.
There are small, separate rules for document starts, broken negations,
metadata headers, and non-text markers. This misses multilingual fragments
and much of the component's context dependence.
"""
import math
import re
from functools import lru_cache
from wordfreq import top_n_list, zipf_frequency

READS = ()

@lru_cache(maxsize=150000)
def frequency(word):
    return zipf_frequency(word.lower(), 'en') if word else 0.0

# Sum the corpus frequencies of common words sharing each ending.
ending_mass = {}
for word in top_n_list('en', 50000):
    if word.isascii() and word.isalpha():
        mass = 10 ** frequency(word)
        for length in range(2, min(18, len(word))):
            ending = word[-length:]
            ending_mass[ending] = ending_mass.get(ending, 0.0) + mass
ending_frequency = {s: math.log10(m) for s, m in ending_mass.items()}
del ending_mass

NEGATED_AUXILIARY_STEMS = {
    'aren', 'isn', 'wasn', 'weren', 'hasn', 'haven', 'hadn', 'doesn',
    'didn', 'don', 'couldn', 'wouldn', 'shouldn', 'mustn', 'needn',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    start = carry is None or carry[0] != doc
    if start:
        word, prior, separator, word_separator, previous, position = (
            '', '', '', '', '', 0
        )
    else:
        _, word, prior, separator, word_separator, previous, position = carry
    clean = token.strip().lower()
    letters = clean.isascii() and clean.isalpha()
    continuation = bool(word and token and token[0].isascii()
                        and token[0].isalpha())
    gap = repair_gain = 0.0
    if letters:
        if continuation:
            word = (word + clean)[-40:]
        else:
            if word:
                prior, separator = word, ''
            leading = token[:len(token) - len(token.lstrip())]
            word_separator = separator + leading
            word = clean
        whole_frequency = frequency(word)
        gap = ending_frequency.get(word, 0.0) - whole_frequency
        interrupted = (prior and word_separator and
                       all(c.isspace() or c == '-' for c in word_separator))
        if interrupted:
            repair_gain = frequency(prior + word) - whole_frequency
    else:
        # Remember the last word across punctuation, but only whitespace and
        # hyphens are subsequently eligible for spelling repair.
        tail = re.search(r'[A-Za-z]+$', token)
        if word:
            prior, separator = word, ''
        if tail:
            word = tail.group().lower()
            word_separator = token[:tail.start()]
        else:
            word = ''
            separator = (separator + token)[-100:]

    value = -0.003
    if start:
        value = -0.05
        vowels = sum(c in 'aeiouy' for c in clean)
        if len(clean) > 11:
            value = 0.21
        elif (vowels / max(1, len(clean)) > 2 / 3
              and not token[:1].isspace()):
            value = -0.385
    elif gap > 3.5:
        value = 0.15
    if repair_gain > 2.0:
        value = 0.8

    # Readable exceptions for particular grammatical / markup functions.
    if token == "'t" and previous.strip() == 'n':
        value = 1.4
    elif clean == 't' and previous.strip() in NEGATED_AUXILIARY_STEMS:
        value = 0.28
    if token == '<think>':
        value = -0.21
    if not start and token in ('<|im_start|>', '<|im_end|>'):
        value = -0.047
    if '\x00' in token:
        value = -0.37
    if start and token == 'Title':
        value = -0.974
    elif position == 1 and previous == 'Title' and token == ':':
        value = 3.343
    state = (doc, word, prior, separator, word_separator, token, position + 1)
    return state, float(value)

"""Detect 'and' conjunctions in several languages, not general conjunctions.

English 'and' has a moderate response, weakened after numbers, single-letter
variables, punctuation and code-like lines. Other 'and' words have their own
strengths. Preceding words' dictionary frequencies help distinguish Romance
conjunctions (y, e, et) from variables, fragments and English citations.
Quotes following colons receive a small response, larger for 'type' fields.
"""
from functools import lru_cache
import re
from wordfreq import zipf_frequency

READS = ()
AND_WORDS = {
    'und': 2.02, 'и': 0.80, 'і': 1.27, 'og': 2.28,
    'och': 2.70, 'și': 1.92, 'és': 1.57, 'và': 1.07,
    'oraz': 0.69, 'و': 1.25,
}
LANGUAGES = ('en', 'es', 'fr', 'it', 'pt')
ROMANCE = {
    'y': ('es',), 'et': ('fr',), 'e': ('it', 'pt'), 'ed': ('it',),
}
STRENGTH = {'y': 2.9, 'e': 2.7, 'et': 2.5, 'ed': 2.5}
CODE = re.compile(
    r'^\s*(?:if|elif|while|assert|return|for)\b|==|!=|<=|>='
    r'|\w+\.\w+\(|\w+\s*=\s*\w+'
)


def recent_text(prefix):
    start = max(0, prefix.position - 48)
    doc = prefix.document_ids[-1]
    while start < prefix.position and prefix.document_ids[start] != doc:
        start += 1
    return b''.join(prefix.token_bytes[start:-1]).decode('utf-8', 'ignore')


@lru_cache(maxsize=8192)
def language_scores(word):
    return tuple(zipf_frequency(word, lang) for lang in LANGUAGES)


def romance_strength(prefix, word):
    words = re.findall(r'[^\W\d_]{2,}', recent_text(prefix).lower())[-20:]
    if not words:
        return 0.0
    scores = {lang: sum(language_scores(w)[i] for w in words) / len(words)
              for i, lang in enumerate(LANGUAGES)}
    native = max(scores[lang] for lang in ROMANCE[word])
    other = max(score for lang, score in scores.items()
                if lang not in ROMANCE[word])
    # Require a clear preference for the conjunction's language.
    return min(1.0, max(0.0, 3.75 * (native - other) - 0.25))


def english_and(prefix, token, previous):
    if not previous:
        return 0.45
    value = 1.20
    prev = previous.strip()
    if CODE.search(recent_text(prefix).rsplit('\n', 1)[-1]):
        value -= 0.18
    if re.search(r'\d[.,%)]?$', previous):
        value -= 0.37
    if len(prev) == 1 and prev.isalpha():
        value -= 0.17
    if prev and not prev[-1].isalnum():
        value -= 0.12
    if not token[:1].isspace():
        value += 0.20
    if token.strip() != 'and':
        value -= 0.08
    return value


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    previous = ''
    if prefix.position and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2]
    boundary = (token[:1].isspace() or not previous
                or not previous[-1:].isalpha())
    value = 0.0
    if word == '和':
        value = 0.50
    elif boundary and word == 'and':
        value = english_and(prefix, token, previous)
    elif boundary and word in AND_WORDS:
        value = AND_WORDS[word]
    elif boundary and word in ROMANCE:
        value = STRENGTH[word] * romance_strength(prefix, word)
    elif token[:1].isspace() and token.strip() in ('ve', 'dan', 'ja'):
        value = {'ve': 0.97, 'dan': 1.73, 'ja': 1.70}[word]
    elif word in ('και', 'αι') and (word == 'και' or previous.endswith('κ')):
        value = 4.0
    elif token == ' "' and previous.rstrip().endswith(':'):
        value = 0.53
        if re.search(r'["\']type["\']\s*:\s*$', recent_text(prefix)):
            value = 1.0
    return None, value

"""Approximate source-code definition boundaries from a short syntax buffer.

A type/name pair or parameter annotation makes '=' strongly positive. Const/let/var
bindings and JavaScript import bindings also respond. Function signature ends
are positive; separators after declarations without initializers are negative.
Most text, mathematical equations and ordinary calls receive zero.
Rare word-specific effects and longer-range context are not modeled.
"""
import re

READS = ()
NAME = r'[A-Za-z_$][\w$]*'
BUILTIN = set((
    'int long short byte char float double bool boolean string void auto '
    'size_t unsigned signed String Object Integer Character Boolean Double '
    'Float Byte Short Long str bytes list dict tuple set'
).split())
CONNECTIVES = set('if else then where and or not for while return from'.split())
TYPE = (
    r'(?:[A-Za-z_]\w*(?:(?:::|\.)\w+)*|(?:struct|enum|union)\s+\w+)'
    r'(?:[ \t]*<[^;{}=\n]+>)?(?:[ \t]+const)?[\[\]*&?^ ]*'
)
DECL = re.compile(rf'(?<![\w.])({TYPE})[ \t]+[ *&^]*({NAME})[ \t]*(?:\[[^]\n]*\][ \t]*)*\Z')
BIND = re.compile(
    rf'\b(const|let|var)[ \t]+(?:mut[ \t]+)?(?:{NAME}|\{{[^{{}}]*\}})'
    r'(?:[ \t]*:[^;{}=\n]+)?[ \t]*\Z'
)
IMPORT = re.compile(
    r'\bimport[ \t]+(?:\w+[ \t]*(?:,[ \t]*)?)?'
    r'(?:\{[^}]*\}|\*[ \t]+as[ \t]+\w+)?[ \t]*\Z'
)


def declaration(text, code):
    """Type/name syntax, with built-in types and familiar type-name conventions."""
    m = DECL.search(text)
    if not m:
        return False
    t = m[1].strip(' *&?^[]')
    root = re.split(r'[<. :]', t)[0]
    if root.lower() in CONNECTIVES:
        return False
    if root not in BUILTIN and not re.fullmatch(r'[uif]\d+', root):
        if not (root[:1].isupper() or '_' in root or
                re.search(r'[a-z][A-Z]', root) or '::' in t):
            return False
        if not code and not (re.search(r'[a-z][A-Z]',root) or '::' in t):
            return False
    line = text[max(text.rfind(';'),text.rfind('\n'),text.rfind('{'))+1:]
    return not ('"' in line or "'" in line)


def signature(text, token, code):
    """Find the opening parenthesis, ignoring complete nested argument lists."""
    tail = text.rstrip()
    if '{' in token and tail.endswith(')'):
        tail = tail[:-1]
    head = tail if token.strip().startswith('()') else ''
    if not head:
        depth = 0
        for i in range(len(tail)-1,-1,-1):
            if tail[i] == ')':
                depth += 1
            elif tail[i] == '(':
                if depth == 0:
                    head = tail[:i]
                    break
                depth -= 1
    explicit = bool(re.search(rf'\b(?:function|def|fn|func)\s+{NAME}\s*$',head))
    control = bool(re.search(r'\b(?:if|while|for|switch|with)\s*$',head))
    constructor = bool(re.search(rf'\b(?:public|private|protected)\s+{NAME}\s*$',head))
    method = explicit or constructor or declaration(head,code)
    return method, explicit, control


def predict(s, before):
    q = s.strip()
    if q == 'from':
        return 4.8 if IMPORT.search(before.replace('\\n','\n').replace('\\t','\t')) else 0.0
    assign = q == '=' or bool(re.fullmatch(r'=[A-Za-z_$]\w*',q))
    brace = '{' in q and bool(re.fullmatch(r'[(){\s]+',q))
    close = q in (')','()','):', '():')
    semi = q.startswith((';',');','));'))
    # Other tokens do not require a syntax scan.
    if not (assign or brace or close or semi or q == ':=' or not q):
        return 0.0
    text = before.replace('\\n','\n').replace('\\t','\t').replace('`',' ')
    code = bool(re.search(
        r'[;{}][ \t]*(?:\n|$)|(?:^|\n)[ \t]*(?:\d+\s+)?'
        r'(?:import|package|#include|class|public|private|const|let|var|def|fn|func)\b',
        text
    ) or re.search(r'```[A-Za-z+#]+[ \t]*\n',before))
    typed = declaration(text[-240:],code)
    annotation = re.search(rf'({NAME})[ \t]*:[ \t]*({TYPE})[ \t]*\Z',text[-240:])
    if annotation:
        typed = typed or declaration(annotation[2]+' '+annotation[1],code)
    if assign:
        binding = BIND.search(text[-240:])
        if binding:
            return {'const':4.9, 'let':3.7, 'var':2.6}[binding[1]]
        if typed:
            return 5.7 if s.startswith(' ') else (4.3 if q == '=' else 2.5)
        return 2.0 if re.search(r'\$\w+\s*$',text) else (0.4 if code else 0.0)
    if q == ':=':
        return 1.2
    if brace or close:
        method, explicit, control = signature(text[-500:],s,code)
        if brace:
            if method and not control:
                return 1.55 if explicit else 2.35
            return -0.1 if control else (0.3 if '\n' in s else 0.0)
        if typed:
            return 2.0 if method or q.startswith('()') else 0.95
        return 0.55 if explicit else 0.0
    if semi:
        return (-1.0 if '\n' in s else -0.16) if typed else 0.0
    if not q:
        field = re.sub(r';\s*\Z','',text)
        return -0.65 if field != text and declaration(field,code) else 0.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc,(before+token)[-600:]),predict(token,before)

programs.haiku:
"""Declaration initialiser. The '=' (or ':=') that gives a value to a newly declared
variable in code fires strongly: `int n = `, `for (int i = `, `String s = `,
`List<Item> xs = `, `Map<K, V> m = `, `const rule = `, `let x = `, `var y = `,
`name: string = `. Declarations opened by let/var/mut fire a bit less. Weak on PHP
`$x = `, and on the '{' that opens a function body after `()`. Plain assignments
(`a.b = `, `x = `, `a[0] = `) and prose stay near 0."""
import re

TYPE_WORDS = frozenset(
    "int long short char byte float double bool boolean String string const let var "
    "mut final static private public protected unsigned auto val str dict "
    "uint8_t uint16_t uint32_t uint64_t int32_t int64_t size_t Integer".split()
)
KEYWORD_DECL = re.compile(r"^\s*(const|let|var|val|type|typealias|final)\s+[\w$]+\s*(:[^=]*)?$")
READS = ()


def _line_before(token_strings):
    # text on the current line before the newest token
    parts = []
    for tok in reversed(token_strings[:-1]):
        if "\n" in tok:
            parts.append(tok.split("\n")[-1])
            break
        parts.append(tok)
    return "".join(reversed(parts))


def _is_type(word, indented):
    if word in TYPE_WORDS or word.endswith((">", "*", "&")):
        return True
    # a capitalised class name: only inside indented code, or CamelCase
    return word[:1].isupper() and (indented or re.search(r"[a-z][A-Z]", word) is not None)


def _value(line):
    """How strongly an '=' ending this line initialises a newly declared variable."""
    if KEYWORD_DECL.match(line):
        return 3.5 if line.split()[0] in ("let", "var") else 5.0
    m = re.search(r"([A-Za-z_]\w*)\s*$", line)
    if not m:
        return 1.3 if re.search(r"\$\w+\s*$", line) else 0.0
    before = line[: m.start()]
    indented = line[:1] in (" ", "\t")
    ann = re.search(r"\w+\s*:\s*([\w<>\[\]*&]+)\s*$", line)
    if ann and _is_type(ann.group(1), indented):
        return 5.0
    word = re.search(r"([\w<>\[\]*&]+)\s+$", before)
    if word and _is_type(word.group(1), indented):
        return 3.5 if word.group(1) in ("let", "var", "mut") else 5.0
    return 0.0


def step(carry, prefix, upstream):
    s = prefix.token_strings
    tok = s[-1].strip()
    value = 0.0
    if tok in ("=", ":="):
        value = _value(_line_before(s).rstrip())
    elif tok in ("{", "{\n") and len(s) > 1:
        prev = s[-2].rstrip()
        if prev.endswith("()"):
            value = 2.0
        elif prev.endswith(")"):
            value = 1.0
    return carry, value

programs.sol:
"""Approximate a short di/dis/dif/dys spelling-fragment response.

The response is strongest when d and the following fragment straddle a
token boundary. Complete words and ordinary grammatical endings are weak.
Cyrillic is transliterated by a fixed dictionary. Related Greek spellings
and Japanese di+su have separate rules, as do Russian raz-/ras- prefixes.
Whole English roots and camel-case word boundaries suppress split responses.
The last 24 characters are retained, reset at document boundaries.
"""
import unicodedata
from functools import lru_cache

import regex as re
from anyascii import anyascii
import wordnet

READS = ()
CYRILLIC = re.compile(r'\p{Script=Cyrillic}+')


def unaccent(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text)
                   if not unicodedata.combining(c))


@lru_cache(maxsize=32768)
def response(token, previous):
    # Katakana di followed by su spells the same short dis sound.
    if previous.endswith('ディ') and token.startswith('ス'):
        return 6.5

    s = unaccent(token.lower()).replace('ſ', 's')
    p = unaccent(previous.lower()).replace('ſ', 's')

    # Greek delta + i/eta is positive; delta + a/e/o is negative.
    if p.endswith('δ') and s:
        if s[0] == 'ι':
            return 4.9
        if s[0] == 'η':
            return 4.0
        if s[0] == 'υ':
            return 0.4
        if s[0] in 'αεοω':
            return -1.8
    if p.endswith('δε') and s == 'ν':
        return -3.7
    if p.endswith('δι') and s and s[0].isalpha():
        if s[0] == 'α':
            return 4.7
        if s[0] == 'κ':
            return 2.8
        return 0.6

    # Apply the Latin fragment rules to Cyrillic too, but not to other scripts.
    s = CYRILLIC.sub(lambda m: anyascii(m.group()), s)
    p = CYRILLIC.sub(lambda m: anyascii(m.group()), p)
    if p.endswith(('di', 'dy')) and s and s[0] in 'sf':
        return 2.1 if len(s) <= 2 else 0.3
    if p.endswith('d') and s and s[0] in 'iy':
        # Do not read across a camel-case boundary or a complete English root.
        word = re.search(r'[A-Za-z]+$', previous)
        if word:
            root = word.group()
            if token[0].isupper() and not root.isupper():
                return 0.0
            if (len(root) >= 5 and not root.lower().endswith('ed')
                    and wordnet.parts_of_speech(root.lower())
                    & {'noun', 'adjective'}):
                return 0.0
        tail = s[1:]
        if tail == 's':
            return 6.0
        if tail in ('st', 'ss', 'sc', 'sm', 'se', 'sk', 'z'):
            return 3.8
        if tail == 'sh':
            return 2.1
        if tail.startswith('s'):
            return 0.6
        if tail in ('f', 'ff'):
            return 4.1
        if tail.startswith('f'):
            return 0.1
        if tail in ('m', 'v', 'b', 'ch'):
            return 1.8
        if tail.startswith('r'):
            return 0.6
        return 0.2

    # A fragment can also be inside one token, including redis or undis.
    matches = list(re.finditer(r'd[iy]', s))
    if matches:
        m = matches[-1]
        tail = s[m.end():]
        title = token.lstrip().startswith('D') and not token.isupper()
        scale = 0.72 if title else 1.0
        if tail in ('s', 'st', 'ss'):
            return 2.5 * scale
        if tail in ('f', 'ff'):
            return 1.5 * scale
        if tail == 'sh':
            return (1.5 if m.start() == 0 else 0.15) * scale
        # Avoid did, -ding, -dies, -died and longer adjectival endings.
        if (len(tail) <= 2 and m.start() <= 1
                and tail not in ('d', 'ng', 'es', 'ed', 'an', 'on', 'al')):
            return 0.2
        return 0.0
    word = token.strip().lower()
    if len(word) <= 4 and word.startswith(('раз', 'рас')):
        return 0.75
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = response(token, previous)
    return (document, (previous + token)[-24:]), value

"""Approximate a pre-final character / predicate-ending detector.

The strongest cue is a UTF-8 character awaiting its last byte, especially in
Han and Hangul text. Plain Japanese verb/adjective endings are another cue;
polite endings and grammatical particles are not. Korean predicate endings
get a smaller response. Ordinary text stays near zero. A small negative bias
at document starts approximates a separate start-of-document effect.
The constants are coarse averages, not a token-by-token lookup.
"""
import regex

READS = ()
JAPANESE = regex.compile(r'\p{Hiragana}')
KOREAN = regex.compile(r'\p{Hangul}')
HAN_OR_HANGUL = regex.compile(r'[\p{Han}\p{Hangul}]')
GREEK = regex.compile(r'\p{Greek}')
# Particles, demonstratives and common adverbs that resemble conjugations.
FUNCTION_WORDS = set("""
    は が を に へ と も の や か ね よ で から まで ので のに
    には では とは この その あの どの これ それ あれ どれ
    こと もの ため よう さん そう こう という まだ くらい
    ぐらい よく なく ではなく として に関して
""".split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    tail, need = (b'', 0) if first else carry[1:]
    raw = prefix.token_bytes[-1]
    for b in raw:
        if b < 128:
            tail, need = b'', 0
        elif b >= 192:
            tail = bytes([b])
            need = 1 if b < 224 else 2 if b < 240 else 3
        elif need:
            tail += bytes([b])
            need -= 1
            if not need:
                tail = b''

    s = prefix.token_strings[-1].strip()
    value = -0.002
    if need == 1:
        # Filling the missing byte with 0x80 identifies the character's script.
        approximate_character = (tail + b'\x80').decode('utf8', 'replace')
        value = 0.30 if len(tail) == 1 else 0.16
        if HAN_OR_HANGUL.search(approximate_character):
            value = 0.72
        elif len(tail) == 2 and GREEK.search(approximate_character):
            value = 1.50
        elif len(tail) == 3:  # Supplementary-plane characters, often emoji.
            value = 0.85
    elif need:
        value = 0.09
    elif JAPANESE.search(s):
        value = 0.04
        if s in FUNCTION_WORDS:
            value = -0.05
        elif s.endswith(('ます', 'です', 'ました', 'でした', 'ません')):
            value = 0.05
        elif s.endswith(('いる', 'いた', 'った', 'ない')):
            value = 1.05
        elif s.endswith(('た', 'だ')):
            value = 0.85
        elif s.endswith(('て', 'で')):
            value = 0.60
        elif s.endswith('い'):
            value = 0.65
        elif s.endswith(tuple('うくぐすつぬぶむる')):
            value = 0.68
        elif s.endswith('な'):
            value = 0.37
    elif KOREAN.search(s):
        value = -0.06
        if s.endswith(('니다', '습니다')):
            value = 0.02
        elif s.endswith((
            '하는', '되는', '있는', '없는', '않는', '던',
            '않을', '있을', '없을',
        )):
            value = 0.85
        elif s.endswith(('다', '는', '한', '할', '된', '될')):
            value = 0.50
        elif s.endswith(('어', '아', '여', '해', '워', '려', '러')):
            value = 0.40
        elif s.endswith('은'):
            value = 0.18
    if first and not s.startswith('<|'):
        value = -0.18
    return (doc, tail, need), value

"""An Indonesian spelling contrast, with a few independent formatting responses.

Completed words that are much commoner in Indonesian than other Latin-script
languages establish a fading language cue. In that context, short se-/me-
openings and some of their continuations are negative; personal pronouns,
-nya, -ku/-mu and ia endings are positive. Small vowel/fragment corrections
account for weaker responses. All state resets at document boundaries.

Separately recognize initial end-of-text/carriage returns, a Title: header,
and repeated pairs of middle dots. These are not Indonesian-language rules.
"""
from functools import lru_cache
from wordfreq import available_languages, zipf_frequency

READS = ()
OTHER_LANGUAGES = tuple(
    lang for lang in (
        'en es fr pt it de nl tr vi sv da nb fi pl cs sk hu ro ca '
        'sh sl lt lv fil'
    ).split() if lang in available_languages()
)
PRONOUNS = frozenset(
    'anda kamu kami kita kalian engkau aku saya mereka'.split()
)


@lru_cache(maxsize=40000)
def language_evidence(word):
    """Positive for distinctive, frequent Indonesian words; negative otherwise."""
    if not word.isalpha() or len(word) < 2:
        return 0.0
    if not word.isascii():
        return -1.0
    frequency = zipf_frequency(word, 'id')
    if frequency < 3.5:
        return -0.5 if zipf_frequency(word, 'en') > 4.0 else 0.0
    other = max(zipf_frequency(word, lang) for lang in OTHER_LANGUAGES)
    if frequency - other > 0.7:
        return min(2.0, frequency - other - 0.3)
    return -0.7 if other - frequency > 0.7 else 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        evidence, word, parts, position, only_returns = 0.0, '', 0, 0, True
    else:
        _, evidence, word, parts, position, only_returns = carry
    s = text.lower().strip()
    boundary = not word or bool(
        text and (text[0].isspace() or not text[0].isalpha())
    )
    previous = word.lower()
    evidence *= 0.97
    if boundary:
        evidence = max(0.0, min(4.0, evidence + language_evidence(previous)))
    gate = min(1.0, max(0.0, evidence - 0.5))

    value = 0.0
    if position == 0 and text == '<|endoftext|>':
        value = -2.6
    elif text == ':' and word == 'Title' and position <= 3:
        value = 3.8
    elif text == '··' and word == '··':
        value = -2.14
    elif only_returns and text == '\r':
        value = -1.25

    if s.isascii() and s.isalpha():
        word = text.strip() if boundary else (word + text)[-40:]
        parts = 1 if boundary else parts + 1
        whole = word.lower()
        response = 0.0
        if len(s) <= 6:
            response += -0.26 * ('e' in s) + 0.32 * ('u' in s)
            response += 0.08 * ('a' in s) + 0.08 * ('o' in s)
            response -= 0.13 * (s[-1] in 'rl')
            if boundary and len(s) == 1 and s not in 'aeiou':
                response += 0.45
        if boundary:
            if s == 'se' or (
                len(s) == 3 and s.startswith('se') and s[-1] not in 'aeiouh'
            ):
                response -= 3.2
            if s in ('sel', 'ses'):
                response -= 3.1
            if s.startswith('me') and len(s) <= 4:
                response -= 0.23
            if s in ('mel', 'mes'):
                response -= 3.35
        else:
            response += 2.0 * s.endswith('nya')
            response += 4.7 * (s in ('ku', 'mu'))
            response += 1.6 * (s == 'ia')
            response -= 2.0 * (previous == 'se')
            response -= 0.32 * ('e' in previous and parts == 2)
            response -= 2.3 * whole.startswith('melal')
            response -= 0.26 * s.endswith('r')
        response += 4.7 * (whole in ('ia', 'dia'))
        response += 2.2 * (whole in PRONOUNS)
        response += 2.5 * (whole in ('dir', 'diri'))
        response -= 5.7 * (whole == 'selur')
        value += gate * response
    else:
        if text.startswith('-') and text[1:].isalpha():
            value += gate
        word, parts = ('··' if text == '··' else ''), 0
    if text == '<|endoftext|>':
        evidence = 0.0
    carry = (
        document, evidence, word, parts, position + 1,
        only_returns and text == '\r',
    )
    return carry, float(value)

"""A sparse approximation of the component's positive and negative cues.

Positive cues are selected TeX command starts, citation/link brackets,
and Japanese nominalizers and demonstratives (also Korean '그', 'that').
事 is strong after kana appears, except after 仕, making 仕事 ('work').
In that Japanese context, compound Han words and unfinished Han-character
byte fragments receive small negative biases. Other text stays near zero.
This does not capture the varied responses to individual Han characters.
State resets at document boundaries and remembers the previous token's
relation to a backslash, to recognize the split command 'new' + 'command'.
"""
import regex

READS = ()
KANA = regex.compile(r'[\p{Script=Hiragana}\p{Script=Katakana}]')
HAN_WORD = regex.compile(r'\p{Script=Han}{2,}')

# Initial pieces, not whole commands: e.g. h(bar/fill), q(uad),
# con(g), opl(us), use(package), and set(length).
DISPLAY_LAYOUT = {'display', 'caption', 'col', 'column', 'center', 'small'}
DOCUMENT_SETUP = {'label', 'input', 'include', 'use', 'set', 'par'}
MATH_NOTATION = {'h', 'q', 'hs', 'lim', 'not', 'non', 'cd', 'ar',
                 'ot', 'con', 'opl', 'map', 'back', 'cr', 'start'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        japanese, previous, previous_command = False, '', False
    else:
        _, japanese, previous, previous_command = carry
    s = prefix.token_strings[-1]
    japanese = japanese or bool(KANA.search(s))
    command = previous.endswith('\\')
    value = -0.004

    if command:
        if s == 'cite':
            value = 7.8
        elif s == 'ref':
            value = 5.6
        elif s == 'tag':
            value = 4.0
        elif s in {'new', 'renew', 'define'}:
            value = 4.5
        elif s in DISPLAY_LAYOUT:
            value = 3.5
        elif s in DOCUMENT_SETUP:
            value = 2.2
        elif s in MATH_NOTATION:
            value = 1.6
        elif s in {'cup', 'cap', 'big', 'Big', 'subset'}:
            value = 0.7
    elif previous_command and previous in {'new', 'renew'} and s == 'command':
        value = 8.6
    elif s == ' [@' or (s == '[@' and previous.endswith('\xa0')):
        value = 2.5
    elif s in {' [#', '[#'}:
        value = 3.0
    elif s == 'permalink':
        value = 1.4
    elif s == 'その':
        value = 4.4 if first else 6.2
    elif s in {'それ', 'それが', 'そこ'}:
        value = 2.3
    elif s in {'こと', 'ことは', 'ること', 'すること', 'することが'}:
        value = 2.4
    elif s == 'ことが':
        value = 3.0
    elif s in {'ことを', 'ことも', 'したこと', 'のこと'}:
        value = 1.7
    elif 'こと' in s:
        value = 0.4
    elif japanese and s in {'事', '事を', '事が', '事に', '事は'}:
        if previous.endswith('仕'):
            value = 1.2
        else:
            value = 7.6 if s == '事' else 4.8
    elif s == ' 그':
        value = 3.6
    elif s == '그' and (first or not previous[-1:].isalnum()):
        value = 1.9
    elif s == '\xa0':
        value = 0.11
    elif japanese and '\ufffd' in s:
        # E4--E9 are the UTF-8 lead bytes of most Han characters.
        b = prefix.token_bytes[-1]
        if b and 0xE4 <= b[0] <= 0xE9:
            value = -0.6
    elif japanese and HAN_WORD.fullmatch(s):
        value = -0.15
    return (doc, japanese, s, command), value

programs.haiku:
"""Fires on words that are part of LaTeX reference, citation, label and macro-definition
commands (the word right after a backslash, e.g. \\cite, \\ref, \\eqref, \\footnote,
\\label, \\displaystyle, \\tag, \\newcommand), and on Japanese/Korean 'that' and
'matter/thing' words (その, それ, そこ, 그, 事, こと)."""

READS = ()

LATEX_CMD = {"cite": 7.0, "foot": 7.0, "ref": 6.0, "eq": 7.0, "new": 3.6,
             "display": 3.5, "tag": 4.0, "label": 2.0, "input": 1.8, "lim": 1.6}
JA_THAT = {"その": 6.3, "それ": 2.3, "そこ": 2.7, "그": 2.1, " 그": 3.3}
JA_THING = {"事": 2.8, "事が": 5.0, "事を": 5.5, "こと": 2.3, "ことが": 2.9, "ことは": 2.4,
            "ること": 2.1, "すること": 2.2, "ことも": 2.3}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if prev.endswith("\\") and tok in LATEX_CMD:
        return carry, LATEX_CMD[tok]
    if prev == "new" and tok == "command":
        return carry, 7.9
    if prev == "foot" and tok == "notes":
        return carry, 2.0
    if tok in JA_THAT:
        return carry, JA_THAT[tok]
    if tok in JA_THING:
        return carry, JA_THING[tok]
    return carry, 0.0

programs.sol:
"""Sparse responses to presentation markup, not mathematical content.

Track a short text tail within each document. Font/style/size commands in TeX,
selected @ metadata tags/scopes, and numbered-reference label prefixes get
negative values. Doubled middle-dot tokens get a positive value; an initial
run of carriage returns gets a negative value. Other text is zero.
The numbers are rounded training estimates, not an exhaustive TeX interpreter;
other lexical and non-Latin responses are deliberately omitted.
"""
import re

READS = ()

# TeX font selectors, including their text/math variants.
FONTS = {
    'bf': -9.5, 'it': -10.5, 'rm': -8.5, 'cal': -9.0,
    'em': -8.4, 'tt': -2.0, 'bm': -1.7, 'bb': -3.0,
    'pmb': -6.0, 'textbf': -1.5, 'textit': -3.4,
    'textnormal': -2.6, 'mathrm': -0.5,
    'mathfrak': -2.0, 'mathpzc': -0.8,
}
# Presentation controls and delimiter macros. Some names are split across
# tokens: display is the first part of displaystyle, lf of lfloor, etc.
LAYOUT = {
    'display': -3.4, 'displaystyle': -5.8,
    'script': -2.9, 'scriptscript': -2.7,
    'scriptstyle': -6.5, 'scriptscriptstyle': -7.3,
    'large': -10.6, 'Large': -14.0,
    'limits': -7.3, 'nolimits': -2.3, 'cr': -5.2,
    'bigg': -5.8, 'biggl': -8.5, 'biggr': -4.1,
    'lf': -3.6, 'rf': -1.9, 'lt': -4.3, 'lbrace': -5.1,
    'pars': -8.0, 'bracks': -1.5, 'raise': -2.2,
    'pu': -1.8, 'ce': -1.3, 'medskip': -4.6,
}
# Documentation tags and TypeScript package scopes.
AT_METADATA = {
    'type': -4.7, 'var': -1.8,
    'description': -3.0, 'returns': -1.9, 'return': -0.4,
    'types': -2.8, 'typescript': -2.1,
}
# Initial pieces of common numbered bibliography/reference labels.
CITATION_LABELS = {
    'B': -4.7, 'b': -5.7, 'CR': -7.8, 'R': -3.1, 'ref': -3.9,
}
COMMAND = re.compile(r'\\([A-Za-z]+)$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, only_cr = '', True
    else:
        _, tail, only_cr = carry
    s = prefix.token_strings[-1]
    new_tail = (tail + s)[-80:]
    value = 0.0
    if s == '\r' and only_cr:
        value = -3.9
    elif s == '··':
        value = 1.32
    elif tail.endswith('@'):
        if tail.endswith('[@'):
            value = CITATION_LABELS.get(s, 0.0)
        elif tail.endswith('{@') and s == 'code':
            value = -6.2
        else:
            value = AT_METADATA.get(s, 0.0)
    else:
        match = COMMAND.search(new_tail)
        if match and s.isascii() and s.isalpha():
            name = match[1]
            value = FONTS.get(name, LAYOUT.get(name, 0.0))
        elif s == 'small' and re.search(r'\\(?:begin|end)\{$', tail):
            value = -2.0
    return (doc, new_tail, only_cr and s == '\r'), float(value)

programs.haiku:
"""Layer-1 MLP down-projection component 1677: a markup-name detector.

It is silent on ordinary prose and code, and turns negative on the name that follows
a markup prefix:
  * after a backslash, the name of a LaTeX font, size or style switch
    (\\Large, \\large, \\it, \\bf, \\rm, \\limits, and the `style` of \\displaystyle);
  * after `[@` or `@`, a citation key (`[@CR45]`, `[@B12]`) or a doc tag (`@type`, `@code`);
  * after `\\big`, the g/l/r of \\bigg, \\bigl, \\bigr.
Values are typical strengths measured on training text; all other tokens get 0.
"""

READS = ()

# LaTeX font / size / style switch names, right after a backslash
LATEX_SWITCHES = {
    "Large": -14.0, "large": -10.0, "it": -11.0, "bf": -10.0, "rm": -8.5,
    "limits": -7.0, "small": -3.0, "display": -3.5, "cr": -5.0,
}
# Citation keys and doc tags, right after "[@" or "@"
AT_NAMES = {"CR": -7.5, "B": -4.7, "b": -4.0, "ref": -4.0, "R": -3.0,
            "type": -4.7, "code": -4.1, "description": -3.0, "types": -2.9}
# Letters that follow "\big" to make \bigg, \bigl, \bigr
BIG_LETTERS = {"g": -5.0, "gl": -5.0, "gr": -5.0}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    value = 0.0
    if prev.endswith("\\") and cur in LATEX_SWITCHES:
        value = LATEX_SWITCHES[cur]
    elif prev == "display" and cur == "style":
        value = -5.2
    elif prev.endswith("@") and cur in AT_NAMES:
        value = AT_NAMES[cur]
    elif prev in ("big", "Big") and cur in BIG_LETTERS:
        value = BIG_LETTERS[cur]
    return carry, float(value)

programs.sol:
"""A surface-word detector for 'on', with a few conventional uses distinguished.

'On' and 'upon' give negative pulses. The pulse nearly disappears after
words about dependence, basis, focus, or effects. It is weaker in several
phrasal verbs, and stronger after sharing/publication verbs. A few foreign
words meaning 'on' also give pulses. Other prepositions have a faint positive
background. A nonbreaking space following a signature dash is another trigger.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

ATTENTION = {'depend', 'focus', 'concentrate'}
BASIS = {
    'base', 'dependent', 'dependence', 'rely', 'emphasis',
    'impact', 'effect', 'influence',
}
PARTICLES = {'go', 'turn', 'put', 'take', 'hold', 'click'}
PUBLICATION = {'share', 'post', 'publish', 'release', 'air', 'play'}
OTHER_PREPOSITIONS = {'in', 'at', 'for', 'from', 'with', 'into', 'about'}
# Surface forms of 'on' in Scandinavian, French, German, Slavic/Portuguese,
# and Arabic text respectively. The strengths differ between languages.
TRANSLATIONS = {
    'på': -0.88,
    'sur': -0.58,
    'auf': -0.29,
    'na': -0.34,
    'على': -0.61,
}


@lru_cache(maxsize=4096)
def roots(word):
    return set(wordnet.base_forms(word)) | {word}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    spaced = bool(token[:1].isspace())
    boundary = spaced or not tail or not tail[-1].isalpha()
    value = 0.002

    if word in {'on', 'upon'} and boundary:
        if word == 'upon':
            value = -0.94 if token.strip()[0].isupper() else -0.84
        else:
            value = -0.55 if token.strip()[0].isupper() else -0.72
            if not tail:
                value = -0.40
        previous = re.findall(r'[a-z]+', tail.lower())
        if previous:
            last = previous[-1]
            # An adverb can intervene: 'depends heavily on'.
            if len(previous) > 1 and 'adverb' in wordnet.parts_of_speech(last):
                last = previous[-2]
            forms = roots(last)
            if forms & ATTENTION:
                value = 0.02
            elif forms & BASIS:
                value = -0.10
            elif forms & PARTICLES:
                value = -0.33
            elif forms & PUBLICATION:
                value = -1.15
            if previous[-2:] == ['and', 'so']:
                value = 0.14
    elif token.lower() in {'-on', '_on'}:
        value = -0.72 if token[0] == '-' else -0.50
    elif spaced and word in TRANSLATIONS:
        value = TRANSLATIONS[word]
    elif spaced and word in OTHER_PREPOSITIONS:
        value = 0.02
    elif token == '\xa0' and tail.rstrip().endswith(('–', '—')):
        value = -0.72

    return (doc, (tail + token)[-100:]), value

programs.haiku:
"""Layer 1 MLP down-projection, component 1678: an "on" detector."""

READS = ()

# How strongly each word pushes the component negative.
ON_WORDS = {" on": -0.7, " upon": -0.8, " On": -0.5, " Upon": -1.0,
            " auf": -0.3, " sur": -0.3, " på": -0.3, " na": -0.3, " op": -0.3}
# "on" inside fixed phrases such as "based on", "depends on", "and so on": about zero.
NOT_ON_AFTER = {"based", "depend", "depends", "depending", "focus", "focused",
                "focuses", "impact", "effect", "rely", "dependent", "so"}


def step(carry, prefix, upstream):
    value = ON_WORDS.get(prefix.token_strings[-1], 0.0)
    if value and len(prefix.token_strings) > 1:
        if prefix.token_strings[-2].strip().lower() in NOT_ON_AFTER:
            value = 0.0
    return carry, value

programs.sol:
"""Recognize textual block markers, chiefly Markdown code fences.

Backtick pairs/triples are strongest after blank lines or colon-ended
introductions, weaker after code-like lines or inline. Strip diff and comment
margins when checking this. Also recognize LaTeX equation openings, diff hunks,
shell here-documents and forum metadata. A document-initial // newline gives
one negative pulse. Otherwise predict near zero. Retain 800 recent characters
and reset them at document boundaries.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    marks = token.strip(' \t\r\n')
