        if before.rstrip().endswith(')'):
            if re.match(r'\s*(?:\d+\s+)?(?:async\s+)?with\b', line):
                return 15.0
            if word == 'AS':
                return 13.0
            if len(before) < 50 and re.search(r"['\"]\)$", before):
                return 10.7
        if re.search(r'\bimport\s+[\w.*]+$', line):
            scientific = re.search(r'\b(numpy|pandas|matplotlib)(?:\.\w+)*$', line)
