            return 5.5
        if re.search(r'\bforeach\s*\(', line):
            return 5.2
        if word == 'AS' and re.search(r'\bWITH\b', line):
            return 9.0
        if word == 'As' and re.search(r'\b(Dim|Sub|Function|Const)\b', line):
