        if re.search(r'\b(SELECT|FROM|SUM)\b', before):
            return 5.0
        if before.endswith((')', ']')) and re.match(
            r'\s*(?:\d+\s+)?(?:return\b|(?:val|let|const|var)\s+|\w+\s*=)',
            line
