            return 6.2 if word.lower() == 'null' else 1.2
        if re.search(r'\bis\s*$', before, re.I):
            return 2.1 if word == 'None' else 1.0
        if word == 'True' and re.search(r'\bwhile\s*$', line):
            return 4.1
        if word == 'False' and re.search(r'\bassert\s*$', before):
            return 0.7
        return 0.0
    if word == 'OVER' and before.rstrip().endswith(')'):
        return 6.8
    if word == 'IF' and re.search(r'\bEND\s*$', before):
        return 3.8
    if word.lower() == 'desc' and re.search(r'\border by\b', line, re.I):
        return 5.0
