The rare, large spikes occur while a document consists entirely of zeros
or entirely of twos. Smaller negative rules cover zero after 3, written
thirty, two after uppercase/lowercase letters, Roman-looking II, and ₂.
Other initial repetitions get a modest background; later unmatched tokens
get a near-zero background. This deliberately omits lexical fine detail.
"""
READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    start = carry is None or carry[0] != document
    if start:
        leading = token
    else:
        leading = carry[1]
        if token != leading:
            leading = None

    if leading == '0':
        value = 3.53645
    elif leading == '2':
        value = 1.5064
    elif leading is not None:
        value = 0.17
    else:
        value = 0.002
        previous = prefix.token_strings[-2].strip()
        if token == '0' and previous == '3':
            value = -0.27
        elif token == '2' and previous.isalpha():
            if previous.isupper():
                value = -0.28
            elif previous.islower():
                value = -0.15
        elif token.strip(' -').casefold() == 'ii':
            value = -0.27
        elif token.strip().casefold() == 'thirty':
            value = -0.24
        elif token.strip() == '₂':
            value = -0.11
    return (document, leading), value

