"""layers.1.mlp.down_proj:1681 -- a "first token of a document" detector.

This component is almost silent everywhere. Its large outputs come from the first token of
each document: documents are packed end to end in a row, and a row's first token counts as
a document start too, since the model resets attention and positions there. On that token
the output depends on what the token is, not on the text before it (there is none):

  * the digit "0": about +3.5 (the strongest case)
  * the digit "2": about +1.5
  * other digits: about +0.15
  * a capitalised word: about +0.3
  * punctuation: about +0.17
  * a lowercase word: about +0.1
  * a special token such as <|im_end|>: about -0.14

Elsewhere the program outputs 0, except for ".com" right after "github" in a URL (about +0.6).
The mid-document signal that remains is small and spread over thousands of tokens, so
this program leaves it out.
"""

READS = ()

FIRST_TOKEN_VALUE = {"0": 3.5, "2": 1.5}


def first_token_value(token):
    if token in FIRST_TOKEN_VALUE:
        return FIRST_TOKEN_VALUE[token]
    if len(token) == 1 and token in "0123456789":
        return 0.15
    if token.startswith("<|"):
        return -0.14
    word = token.lstrip(" ")
    if word == "":
        return 0.0
    if word[0].isupper():
        return 0.3
    if word[0].islower():
        return 0.1
    if word[0].isalpha():
        return 0.08
    return 0.17


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, first_token_value(token)
    if token == ".com" and prefix.token_strings[-2] == "github":
        return carry, 0.6
    return carry, 0.0

