"""A sparse lexical estimate of evaluation and degree words.

Good/better/best and correctness words are stronger immediately after
articles; possessives also strengthen 'best'.  Romance words for 'good'
are particularly strong, including a few split-word completions.  There
are separate spelling responses to Bash, paired middle dots, and an
initial zero.  Everything else is predicted as zero, not as sentiment.
"""
import re

READS = ()

# Inflected French, Portuguese, Spanish and Italian words for 'good'.
FRENCH_GOOD = {'bon', 'bonne', 'bons', 'bonnes'}
PORTUGUESE_GOOD = {'bom', 'boa', 'boas'}
SPANISH_GOOD = {'buen', 'bueno', 'buena', 'buenos', 'buenas'}
ITALIAN_GOOD = {'buon', 'buono', 'buona', 'buoni', 'buone'}
ROMANCE_GOOD = (FRENCH_GOOD | PORTUGUESE_GOOD | SPANISH_GOOD
                | ITALIAN_GOOD)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    before = previous.strip().lower()
    tail = carry[2] if carry and carry[0] == doc else ''
    completed = word
    if token.isalpha() and tail.lower() in ('b', 'bu'):
        joined = (tail + token).lower()
        if joined in ROMANCE_GOOD:
            completed = joined
    article = before in ('a', 'an')
    definite = before == 'the'
    possessive = before in ('my', 'your', 'his', 'her', 'its', 'our', 'their')
    value = 0.0

    if word == 'good':
        value = 1.3 + 2.0 * article + 1.5 * definite
    elif word == 'better':
        value = 0.65 + 2.3 * article + 1.55 * definite
    elif word == 'best':
        value = 0.75 + 2.55 * (definite or before == 'very')
        value += 1.3 * possessive
    elif word == 'bad':
        value = 0.9 + 0.85 * article + 1.15 * definite
    elif word in ('right', 'wrong', 'correct'):
        value = definite * (2.0 if word == 'wrong' else 1.3)
    elif word == 'most':
        value = 0.12 + 1.0 * definite
    elif word == 'more':
        value = 0.17
    elif word == 'well':
        value = 0.18
    elif completed in ROMANCE_GOOD:
        if completed in FRENCH_GOOD:
            value = 7.8
            if completed == word and not token[:1].isspace():
                value = 3.0 if token[:1].islower() else 6.0
            elif completed == 'bon':
                value = 10.0 if token.lstrip()[:1].islower() else 6.0
        elif completed in PORTUGUESE_GOOD:
            value = 8.5 if completed == 'bom' else 5.2
            if completed == 'boa' and not token[:1].isspace():
                value = 2.5
        elif completed in SPANISH_GOOD:
            value = 7.0
            if completed == 'buen':
                value = 8.2 if token.lstrip()[:1].islower() else 5.6
            elif completed == 'bueno':
                value = 4.7
            elif completed == 'buenos' and token.lstrip()[:1].isupper():
                value = 3.0  # often the place name Buenos Aires
        else:
            value = 8.0
    elif word == 'bash':
        value = -5.0 if token.lstrip().startswith('B') else -3.4
    elif token == 'ash' and previous.endswith('b'):
        value = -6.9
    elif not previous and token == '0':
        value = 1.74

    if token == '··':  # paired middle dots, often used in leaders
        value = 2.2
    match = re.search(r'[A-Za-z]+$', tail + token)
    tail = match.group()[-24:] if match else ''
    return (doc, token, tail), value

"""Sparse code-line, data-abbreviation, and formatting cues.

Positive responses favor unfinished code lines: annotations, documentation
signatures, receiver arguments, SQL clause heads, and open markup tags.
Other comma/identifier line endings get smaller responses. Data-format,
address, and identifier abbreviations are positive, especially in code.
Clock labels, anonymous Go struct declarations, initial title fields,
and repeated middle dots have negative responses. This is an approximation,
not a general parser or a complete account of the component.
"""
import re

READS = ()


def line_ending(token, previous, line):
    full = line + token.split('\n', 1)[0].rstrip('\r')
    end = full.rstrip()
    code = re.sub(r'^\s*(?:\d+\s*\t)?\s*', '', end)
    indented = bool(full[:1] and full[:1].isspace())
    short = len(full.strip()) < 25
    if re.search(r'\bself\s*,\s*$', end):
        return 3.7
    if re.search(r'(?:^|\s)@[A-Za-z_]+\s*$', full):
        return 1.2 if previous.lstrip().startswith('@') else 2.05
    if re.fullmatch(r'#\[[^\n]+\]', code):
        return 2.0
    tag = re.search(r'@(param|return|throws|module|license)\b(.*)$', end)
    if tag and not tag[2].endswith('*/'):
        return 1.2 if len(tag[2].split()) <= 3 else 0.0
    if code == 'SELECT':
        return 3.0
    if code in ('INSERT', 'UPDATE', 'DELETE', 'FROM', 'WHERE', 'JOIN',
                'VALUES', 'GROUP BY', 'ORDER BY'):
        return 1.15
    if indented and code == 'get':
        return 2.5
    if code in ('Parameters', 'Returns', 'Raises', 'Attributes',
                'Args', 'Arguments', 'Yields'):
        return 1.1
    if re.fullmatch(r'(?:[+-]\s*)?<\w[\w:.-]*(?:\s+[^<>]*)?', code):
        return 2.1
    char = end[-1:]
    word = previous.strip()
    previous_word = word.isascii() and word.isalpha()
    if char == ',':
        if token.rstrip('\r\n') == ',' and '\r' in token:
            return 1.5
        if not indented:
            return 0.28 if short else 0.05
        if not short:
            return 0.40
        if previous_word:
            return 1.0
        symbols = any(c in full for c in '=$\\_{}[]')
        return 0.32 if symbols or '::' in full or '->' in full else 0.63
    if char == '(':
        return 0.56 if previous_word else 0.34
    tail = re.search(r'[A-Za-z_][A-Za-z_0-9]*$', end)
    word = tail.group() if tail else ''
    if '_' in word or re.search(r'[a-z][A-Z]', word):
        if indented:
            return 0.75 if short else 0.30
        return 0.27 if short else 0.08
    if indented and short and char.isascii() and char.isalpha():
        return 0.35
    return 0.0


def lexical(token, previous, line, position):
    s = token.strip()
    if s == '··':
        return -2.85 if previous in ('', '··') else -0.17
    if token == ':' and previous == 'Title' and position <= 2:
        return -3.84
    if s == 'struct' and line.rstrip().endswith('[]'):
        return -2.2
    if s in ('AM', 'PM', 'UTC') and re.search(
        r'\d{1,2}:\d{2}(?::\d{2})?[\s(]*$', line
    ):
        if s != 'UTC':
            return -1.0
        if line.endswith('\xa0'):
            return -5.2
        return -1.2 if line.rstrip().endswith('(') else -3.0
    match = re.search(
        r'(JSON|URL|URI|UUID|IDs|ID|HTTP|HTTPS|SQL|XML|HTML|CSS|API|GUI)$', s
    )
    if not match:
        if s in ('class', 'struct', 'package', 'import') and position < 2:
            return -0.55
        return 0.0
    if match.start() and (s[match.start() - 1].isupper()
                          or s[match.start() - 1] == '_'):
        return 0.0
    term = match.group()
    spaced = token.startswith(' ')
    attached = match.start() > 0 or (
        previous and not spaced and previous[-1].islower()
