    if term == 'JSON':
        return 3.6 if re.search(r'\breturn\s*$', line) else 1.9
    if term in ('ID', 'IDs', 'UUID'):
        if spaced and line.rstrip().endswith(':'):
            return 2.4
        return 0.12 if spaced else (1.5 if attached else 0.7)
    if term in ('URL', 'URI'):
        if spaced and re.search(r'\bnew\s*$', line):
            return 2.75
        return 0.28 if spaced else (1.5 if attached else 1.0)
    if term in ('HTTP', 'HTTPS'):
        return 0.44 if spaced else 0.90
    return 0.10 if spaced else 0.55


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
