READS = ()
STOPS = 'тдпбкг'
SONORANTS = 'рлмн'
SIBILANTS = 'сзцчшщж'
VOWELS_AND_SOFTENERS = 'аеёиоуыэюяьй'

# Consonants before я, inside its token, and after it, respectively.
