    ('мн', 1.36), (VOWELS_AND_SOFTENERS, -0.75), (SIBILANTS, 1.08),
)
ONSET_YA = (
    ('р', 6.55), ('л', 1.01), ('мн', 0.92),
    (STOPS, 2.09), (SIBILANTS, 0.17),
)
AFTER_YA = (
    ('гкх', 1.36), (SIBILANTS, 2.16), ('нм', 0.86),
    ('тд', 2.76), ('рй', 3.03),
