    'y': (0.72, (('tdkgpb', 1.44), ('zs', 1.19), ('nm', -0.90), ('lr', 0.28))),
    'i': (-0.12, (('tdkgpb', 0.73), ('zs', 0.50), ('lr', 0.46))),
    'j': (0.0, (('tdkgpb', 0.91), ('zs', 0.70), ('nm', -0.39), ('lr', 0.21))),
