        return -0.32
    if text == ' `':
        return -0.84
    if text == '--':
        return -1.63
    if text == 'Title':
        return 0.87
    level = heading_level(text)
    if level:
        return {1: 0.50, 2: 0.93}.get(level, 0.62)
    if '\n' in text:
        return 0.44
    if len(word) <= 2:
        return 0.18
    return 0.57 if word[:1].isupper() else 0.31


def heading_word(text, raw, level):
    word = text.strip()
