        return value if level == 1 else -1.25
    if lower in QUESTION_WORDS:
        return -1.8 if level == 1 else -0.8
    if lower in {'a', 'an', 'the'}:
        value = -3.15 if lower == 'a' else -2.14
        return value if level == 1 else value * 0.7
    if len(word) == 1 and word.isalpha():
        return -2.8 if level == 1 else -1.8
    if word[:1].isupper():
        value = -1.45 if common(word) else -1.15
    else:
        value = -0.9 if common(word) else -0.65
    return value if level == 1 else value * 0.7


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, first = 0, '', ''
