Short Arabic seen (س) fragments and Turkish s-bearing suffixes get negative
values. Arabic length ignores the definite article. Carrying the unfinished word
lets the response extend into a following piece. Persian spelling cues soften the Arabic response. Rare, short repeated-s
pieces have a separate positive cue. These are fitted spelling-category averages,
not a dictionary of words; smaller offsets cover other s letters and chat markers.
"""
from functools import lru_cache
import unicodedata
import regex
from wordfreq import zipf_frequency

READS = ()
ARABIC_BY_LENGTH = (-4.20, -2.76, -2.32, -0.56, -0.17, -0.37)
TURKISH_BY_LENGTH = (-2.23, -1.80, -1.54, -0.71, -0.14, 0.09)
ARABIC_AFTER_S = (-1.66, -0.45, -0.06, 0.02)
TURKISH_AFTER_S = (-1.58, -0.45, -0.12, -0.01)
TURKISH_CUES = frozenset('ıİğĞşŞ')
PERSIAN_CUES = frozenset('پچژگکی')
S_LETTERS = {'ス': -0.07, 'す': -0.06, 'ส': -0.30, 'स': -1.70}
CHAT_MARKERS = {'<think>': 0.46, '</think>': 0.32, '<|im_start|>': -0.13}


def word_character(ch):
    return ch.isalpha() or unicodedata.category(ch).startswith('M')


@lru_cache(maxsize=65536)
def spelling(text):
    letters = ''.join(ch for ch in text if ch.isalpha())
    arabic = bool(regex.search(r'\p{Script=Arabic}', letters))
    latin_s = 's' in text.lower() and bool(
        regex.fullmatch(r'\s*\p{Script=Latin}+', text))
