        core = letters[article.end():] if article else letters
        value += ARABIC_BY_LENGTH[min(len(core), 6) - 1]
        value += 0.77 * bool(article) + 0.52 * repeated
        value -= 0.50 * bool(word) + 0.88 * ('مس' in word + letters)
        value -= 0.47 * (len(core) > 1 and core.endswith('س'))
        if persian:
            value += 1.70 * min(1.0, 3 / max(1, len(core)))
    elif arabic_s and lag < 3 and age < 5:
        value += ARABIC_AFTER_S[min(age, 3)]

    if latin_s and turkish:
        value += TURKISH_BY_LENGTH[min(n, 6) - 1]
        value -= 0.18 * repeated + 0.21 * bool(word)
        value -= 0.11 * (not letters.lower().startswith('s'))
        value -= 0.37 * letters.lower().endswith(('sı', 'si', 'su', 'sü'))
    elif turkish and not latin_s and not arabic and letters:
        if not arabic_s and age < 4:
            value += TURKISH_AFTER_S[min(age, 3)]

    w = (word + text.strip()).lower()
