import math

READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    position = (carry[1] + 1 if carry is not None and
                carry[0] == document else 0)
    state = (document, position)
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if position else ''
    value = 0.0

    if token == ' ':
        if position == 0:
            value = 1.52
        elif previous.endswith(' '):
            width = len(previous) - len(previous.rstrip(' '))
            value = 2.04 + 2.22 / math.sqrt(position + 1)
            value -= 0.03 * min(24, max(0, width - 4))
            if width == 1:
                value -= 0.15
    elif token == '\t':
        if position == 0:
            value = -1.11
        elif previous.endswith('\t'):
            value = 1.35
    elif token == '\xa0':
        if position == 0:
            value = 0.42
        elif previous.endswith('\xa0'):
            value = 1.8
        elif previous.endswith(' '):
            value = 0.5

    return state, value

