import unicodedata

READS = ()
CELTIC = {'mc', 'mac'}
ROMANCE = {'de', 'du', 'le', 'la', 'da', 'di', 'lo', 'del', 'della'}
DUTCH = {'van', 'vander'}
ARTICLES = {'de', 'del', 'da', 'di', 'du', 'do', 'dos', 'das',
            'la', 'le', 'les', 'des', 'dell', 'della'}
PLACE_PREFIXES = {'san', 'santa', 'santo', 'sao', 'são', 'el', 'los',
                 'las', 'tel', 'te', 'ben', 'bin', 'ibn'}
APOSTROPHES = "'’ʼʻ`"
SURNAME_ELISIONS = {'O', 'D', 'M', 'N', 'De', 'О'}


def activation(previous, older, word, token):
