    # A prefix split across tokens still counts, e.g. M + c.
    if word.lower() in CELTIC:
        p = word
    lower = p.lower()
    whole_prefix = word == p
    acronym = len(text) > 1 and text.isupper()
    joined = not token[0].isspace()

    if whole_prefix and lower in DUTCH and text.lower() in {'der', 'de', 'den'}:
        return 5.84 if text.lower() == 'der' else 0.35

    if token[0] in APOSTROPHES:
        tail = token[1:]
        if word in SURNAME_ELISIONS:
            if tail[:1].isupper():
                return 11.37 if len(token) <= 4 else 5.58
            return 6.74 if word in {'O', 'О'} else 1.39
        if word in {'L', 'o', 'd', 'l', 'j', 'c', 'n', 't', 'qu'}:
            if word == 'o':
                return 1.64 if tail == 'clock' else 3.11
            if tail[:1].isupper():
                return 3.47
            return 0.19 if not tail else 0.11
        if word.lower() in {'s', 'c'} and tail == 'm':
            return 6.27                 # s'mores, C'mon
        if word.lower() == 'y' and tail == 'all':
            return 3.05
        if word.lower() in {'ma', 'mad'} and tail == 'am':
            return 2.24
        return 0.0

    if not text[0].isalpha():
        return 0.0
    if text[0].isupper() and (not p.isupper() or len(p) == 1):
        if (whole_prefix and lower in {'de', 'der', 'den'}
                and older.strip().lower() in DUTCH):
            return 0.01 if acronym else (5.71 if lower == 'der' else 0.57)
        if whole_prefix and lower in CELTIC:
            return (3.12 if acronym else 5.68) if joined else 1.19
        if whole_prefix and lower in ROMANCE and joined:
            return 0.54 if acronym else 5.21
        if whole_prefix and lower in DUTCH:
            return 0.01 if acronym else (5.07 if p[0].isupper() else 2.69)
        if whole_prefix and not joined:
            if lower in ARTICLES:
                return 0.01 if acronym else (1.41 if p[0].isupper() else 0.32)
            if lower in PLACE_PREFIXES:
                return 0.01 if acronym else 0.38
