            return 0.87
        if re.fullmatch(r"(?:[ODMN]|De)['’ʼʻ`][A-Z]", word):
            return 4.59 if len(token) <= 3 else 0.59
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = older = word = ''
    else:
        _, previous, older, word = carry
    token = prefix.token_strings[-1].replace("\\'", "'")
    value = activation(previous, older, word, token)
    # Carry only the trailing spelling and two tokens; reset at document boundaries.
    match = re.search(r"[\w'’ʼʻ`]+$", word + token)
    word = match.group()[-40:] if match else ''
    return (doc, token, previous, word), value

