"""Surname starts after a name particle (layers.1.mlp.down_proj:1691).

The component fires on the first capitalized token of a surname that directly
follows a particle inside a personal name, e.g. the "Ne" in "Van Ne(erven)",
the "Le" in "Ashley Carter Mac Le(od)", the "G" in "Jacob de G(rom)", or the
"Car" in "Ernesto De Car(lo)". The particle decides the strength:

- strong: "Van", "van", "Mc", "Mac" (about 5 to 7)
- medium: "Le", "La", "De" (about 3)
- weak: lowercase "de", "del", "di", "da", "du", ... (about 0.4)
- apostrophe prefixes "D'", "O'" (about 0.25)

Everywhere else (lowercase next token, no particle, first token of a
document) it predicts 0, which matches the component's near-zero baseline.
Stateless: it reads the previous and current token only.
"""

READS = ()

STRONG = {"van", " van", "Van", " Van", "Mc", " Mc", "Mac", " Mac", "McC", " McC"}
MEDIUM = {"Le", " Le", "La", " La", "De", " De", "DE"}
WEAK = {"de", " de", "del", " del", "di", " di", "da", " da", "du", " du", "dell", " dell", "des", "della", "do", " do"}
APOSTROPHE = {"'", "’", " O", "O", " D", "D"}

# Typical activation after each kind of particle, fitted on sampled training text.
LEVEL = {}
for group, value in ((STRONG, 5.2), (MEDIUM, 3.2), (WEAK, 0.4), (APOSTROPHE, 0.25)):
    for token in group:
        LEVEL[token] = value


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0 or prefix.document_ids[t - 1] != prefix.document_ids[t]:
        return None, 0.0
    # Only a capitalized token (a surname's first letter) can fire.
    if not prefix.token_strings[t].strip()[:1].isupper():
        return None, 0.0
    return None, float(LEVEL.get(prefix.token_strings[t - 1], 0.0))

"""Layer 1 MLP output feature 1692: a UTF-16 "NUL byte" detector.

When text is stored as UTF-16 and read byte by byte, each ASCII character is followed by a
zero byte: "h\x00a\x00t\x00". This component fires on those zero bytes (token "\x00"), and its
size depends on the character just before it: about 21 after a letter, 14 after a digit,
10 to 10.5 after punctuation or a newline, 12.5 at the start of a document, and only about 3.6
after a space (the space's own zero byte). Elsewhere it is near zero, except for weak negative
values on long runs of underscores (about -1 to -3) and on runs of middle dots (-1.7), which
are decorative rules and leaders.
"""

READS = ()

LETTER_NUL = 21.0     # NUL after an ASCII/other letter
DIGIT_NUL = 14.0      # NUL after a digit
PUNCT_NUL = 10.5      # NUL after punctuation such as "," or "."
NEWLINE_NUL = 10.0    # NUL after a newline or tab
SPACE_NUL = 3.6       # NUL after a space: much weaker
START_NUL = 12.5      # NUL with nothing before it (start of a document) or after another NUL


def nul_strength(prev):
    if prev == "" or prev == "\x00":
        return START_NUL
    if prev == " ":
        return SPACE_NUL
    if prev.isalpha():
        return LETTER_NUL
    if prev.isdigit():
        return DIGIT_NUL
    if prev.isspace():
        return NEWLINE_NUL
    return PUNCT_NUL


def decorative_run(tok):
    """Negative for long runs of underscores (rules, blanks) and middle dots (leaders)."""
    s = tok.strip()
    if s and set(s) == {"·"}:
        return -1.7
    if len(s) >= 4 and set(s) == {"_"}:
        return -min(3.0, 0.1 * len(s) + 0.5)
    return 0.0


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if tok == "\x00":
        return None, nul_strength(prev)
    return None, decorative_run(tok)

