    (-0.10, frozenset(('million', 'billion', 'trillion'))),
    (-0.04, frozenset((
        'all', 'every', 'everyone', 'everybody', 'everything',
    ))),
    (-0.09, frozenset(('various', 'several'))),
    (-0.07, frozenset(('only', 'even', 'yet', 'still'))),
    (-0.06, frozenset((
        'around', 'near', 'nearby', 'within', 'adjacent', 'beside',
    ))),
    (-0.055, frozenset(('complete', 'finish'))),
    (-0.15, frozenset(('annual', 'annually'))),
