    """The component's activation at a document's first token, from its decoded text."""
    core = token.strip()
    if token == "<|endoftext|>":
        return 6.0
    if token.startswith("<|") and token.endswith("|>"):
        return -6.0
    if "�" in token:
        return -2.0
    if not core:
        return 1.5
    if core.lower() == "the":
        return -3.0
    if core.lower() in FUNCTION_WORDS:
        return -1.0
    if any(ord(ch) > 0x24F and not is_cjk(ch) for ch in core):
        return -1.5
    if any(is_cjk(ch) for ch in core):
        return 1.5
    if core.isalpha() and core.isascii() and len(core) >= 3:
        if core.isupper():
            return 3.0
        if core.endswith("ing"):
            return 2.5
        if token[:1].isspace():
            return 3.0
        if core[0].isupper():
            return 5.0
        return min(3.0 + 0.3 * (len(core) - 3), 6.0)
    if core.isdigit():
        return 1.3
    return 1.0


def is_cjk(ch):
    """Chinese, Japanese and Korean characters."""
    return 0x3000 <= ord(ch) <= 0x9FFF or 0xAC00 <= ord(ch) <= 0xD7AF


def step(carry, prefix, upstream):
    """Zero everywhere except a document's first token, where it is that token's value."""
    position = prefix.position
    opens_document = position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not opens_document:
        return None, 0.0
    return None, float(value(prefix.token_strings[-1]))

programs.sol:
"""Sparse negative responses to co-ordination/cooperation spellings and ≡.

The rules recognize a few related word families, not general agreement in
meaning. A split co+i spelling instead gets a modest positive response.
Chinese 协/協 and Korean 협 denote cooperation; 谐/諧 denotes harmony.
The symbol ≡ and the TeX command equiv express congruence. An unfinished word and incomplete UTF-8
bytes let recognition cross token boundaries. Two small punctuation rules
cover repeated middle dots and document-opening line comments. Others get
near-zero predictions.
"""
import codecs
import re
from anyascii import anyascii

READS = ()

# Morphological families, with separate noun/adjective and plural responses.
WORDS = (
    ('coordinates', r'coordinates\Z', -1.05),
    ('coordination', r'coordinat(?:ion|ing|ed|or)\Z', -2.6),
    ('coordinate', r'coordinate\Z', -1.7),
    ('coord', r'coord', -2.2),
    ('co-op', r'^coops?\Z', -4.5),
    ('cooperative', r'cooperativ', -3.4),
    ('cooperate', r'cooperat(?!ion)', -3.0),
    ('cooper', r'cooper(?!ation)', -1.55),
    ('coagulation', r'coag', -3.1),
    ('covariant', r'^covariant', -2.8),
    ('coaxial', r'coaxial', -2.0),
    ('coax', r'coax', -1.2),
    ('coexist', r'coexist', -2.6),
    ('coexpress', r'coex\Z', -4.8),
    ('coinfect', r'coinf\Z', -1.8),
    ('coincide', r'coincid(?:e|es|ed)\Z', -0.9),
    ('congruent', r'congruent\Z', -1.9),
    ('collaborative', r'collaborative\Z', -2.2),
    ('assist', r'assist(?:s|ed|ing)?\Z', -0.45),
    ('association', r'association', -0.25),
    ('agreement', r'agreements?\Z', -0.4),
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', b'', '', 0, '')
    _, old, pending, prior, age, previous_text = carry
    b = prefix.token_bytes[-1]
    raw = pending + b
    text, used = codecs.utf_8_decode(raw, 'ignore', False)
    pending = raw[used:]
    match = re.search(r'[\w-]+\Z', old + text)
    word = match.group()[-80:] if match else ''
    low = anyascii(word).lower().replace('-', '')
    low = low.replace('kooper', 'cooper')
    before = anyascii(old).lower().replace('-', '')
    label, value = '', -0.002
    if before.endswith('co') and text[:1].lower() == 'i':
        value = 2.2

    if '≡' in text:
        value = -8.5 if used > len(b) else -7.0
    elif text == 'equiv' and '\\' in previous_text:
        value = -7.5
    elif any(c in text for c in '协協'):
        if any(c in text for c in '会會'):
            value = -7.5 if len(text.strip()) == 2 else -2.0
        elif len(text.strip()) == 1:
            label = 'cooperation-character'
            value = -15.0 if used > len(b) else -10.0
        else:
            value = -4.6
    elif text.strip() in ('谐', '諧'):
        value = -5.5
    elif '협' in text:
        label = 'cooperation-character'
        value = -14.0 if used > len(b) else -4.2
    elif prior == 'cooperation-character' and text and not text[0].isspace():
        if text in ('调', '調'):
            value = -8.0
        elif text in ('商', '議', '议', '조'):
            value = -5.0
        elif text in ('力', '력'):
            value = -2.3
        elif text == '의':
            value = -1.5
    elif len(text) >= 2 and set(text) == {'·'}:
        value = -0.88
    elif text == '//\n' and previous_text == '<|endoftext|>':
        value = -3.14
    else:
        for name, pattern, strength in WORDS:
            if re.search(pattern, low):
                label, value = name, strength
                break
        if label == 'co-op' and 'co-' not in word.lower():
            label, value = '', -0.002
        if before.endswith('co') and low.endswith('coordin'):
            label, value = 'coord-split', -6.0
        elif before.endswith('ko') and 'cooper' in low:
            label, value = 'cooperate', -6.0
        elif word == 'op' and before == 'co':
            label, value = 'co-op', -5.5
        elif 'coö' in word.lower():
            label, value = 'coord-diaeresis', -8.0
        elif 'koor' in low:
            label, value = 'coord-transliterated', -7.0
        elif 'co-' in word.lower() and label.startswith(('coord', 'cooper')):
            label, value = 'co-hyphenated', -6.0
        elif 'koef' in low and 'koef' not in before:
            label, value = 'coefficient', -5.2
        elif low in ('coef', 'coeff', 'coeft') and before.endswith('co'):
            label, value = 'coefficient', -2.5
        if label == 'agreement' and 'cooperativ' in before:
            value = -3.5

        continuing = prior == label or (
            prior.startswith('coord') and label.startswith('coord'))
        if label and continuing and old and not re.search(r'\s|[^\w-]', text):
            age += 1
            if prior == 'coord-split':
                value = -4.0
            elif label == 'coord-diaeresis':
                value *= 1.25 if age == 1 else 0.45
            elif label in ('co-hyphenated', 'cooperative', 'coord-transliterated'):
                value *= 0.6 ** age
            else:
                value *= 0.1
            if age > 2:
                value = -0.002
        else:
            age = 0
    return (doc, word, pending, label, age, text), value

"""A code-boundary feature: returns, mapping keys, and expression punctuation.

Colons are strongest on object/dictionary fields, weaker on type annotations,
and mostly inactive in prose, stylesheets, or at the end of a line. Quoted
naming keys are particularly strong. Nearby brackets and line layout provide
approximate syntax context, not a complete parser. English uses of statement
keywords and documentation tags are suppressed. Chaining dots, arrows, and
C++'s standard-namespace separator have smaller positive responses. State is a
short suffix, reset at document boundaries.
"""
import re

READS = ()
CLOSING_BRACKETS = {')': '(', ']': '[', '}': '{'}


def enclosing(text):
    """Count bracket characters in an excerpt; string literals are not parsed."""
    stack = []
    for ch in text:
        if ch in '({[':
            stack.append(ch)
        elif ch in ')}]':
            if stack and CLOSING_BRACKETS[ch] == stack[-1]:
                stack.pop()
            else:
                stack.clear()
    return stack[-1] if stack else ''


def quoted_key_value(key, quote):
    if key == 'name':
        return 3.4
    if quote == '"':
        return 1.8 if '_' in key else 2.4
    return 2.25 if len(key) <= 5 else 1.8


def colon_value(before, line, token):
    if '\n' in token:
        return -0.06
    # A separately tokenized closing quote can still introduce a mapping value.
    quoted = re.search(r'''(['"])([^'"\n]{1,100})\1\s*$''', line)
    if quoted:
        lead = line[:quoted.start()].rstrip()
        if not lead or lead.endswith(('{', ',')):
            return 3.0
    m = re.search(r'([A-Za-z_][\w]*|\d+)[ \t]*$', line)
    if not m:
        return 0.02
    word, lead = m.group(1), line[:m.start()]
    bracket = enclosing(before)
    if re.search(r'\blambda\s+[^:]*$', line):
        return 2.5
    if line.count('"') % 2:
        return 0.02
    if bracket and re.search(r'(?:=|\breturn\b).*\?.+$', line):
        return 1.9
    # A Python control-flow colon closes a condition, rather than naming a value.
    if re.match(r'\s*(if|elif|else|for|while|try|except|class|with)\b', line):
        return -0.08
    field = not lead.strip() or bool(re.search(r'[{,(]\s*$', lead))
    declaration = bool(re.match(
        r'\s*(pub(?:\(crate\))?|let|var|const|private|public|protected|readonly)\s+',
        lead,
    ))
    if not field and not declaration:
        return 0.03
    # Semicolon-terminated CSS declarations are not dictionary entries.
    css = re.search(r'(?:\d(?:px|rem|em|%)|absolute|relative|solid|hidden)\s*;', before[-200:])
    if css:
        return -0.05
    if declaration:
        value = 1.8
    elif bracket == '(':
        value = 1.0
    elif bracket == '{':
        value = 2.25
        if re.search(r'\b(interface|type)\s+[^{}]*\{[^{}]*$', before):
            value = 1.0
    elif re.search(r',\s*\n[^\n]*$', before) and not re.search(r'\n\s*\n[^\n]*$', before):
        value = 1.5
    else:
        value = 0.15
    if len(word) == 1 and bracket == '{':
        value = 2.0 if re.search(r'\b(return|const|let|var|def|fn|func)\b|[=;]', before) else 0.9
    if token.startswith(' '):
        value = min(value, 0.6)
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    s = token.strip()
    recent = before.replace('\\n', '\n').replace('\\t', '\t')
    line = recent.rsplit('\n', 1)[-1]
    line = re.sub(r'^\s*[+-](?=\s)', '', line)
    line = re.sub(r'^\s*\d+\t', '', line)
    value = 0.0
    if s.lstrip('\\') in ('":', "':"):
        if '\n' in token:
            value = -0.06
        else:
            quote = s[-2]
            key = before.rsplit(quote, 1)[-1]
            value = quoted_key_value(key, quote)
    elif s == ':':
        value = colon_value(recent, line, token)
    elif s.lstrip(')') in ('return', 'throw', 'break', 'continue', 'yield', 'raise'):
        word = s.lstrip(')')
        indent = line + token[:len(token)-len(token.lstrip())]
        statement = (
            not indent.strip()
            or bool(re.search(r'[;{}:]\s*$', indent))
            or s.startswith(')')
        )
        inline = bool(re.search(r'(?:\bif\b.*\)|\belse)\s*$', line))
        comment = bool(re.match(r'\s*(#|//|\*|:)', line) or line.endswith(('@', '\\', '_', '::')))
        code = (statement or inline) and not comment
        if word == 'return':
            value = 2.4 if code else -0.04
            if code and re.search(r'\b(def|self|elif|None)\b', recent):
                value = 1.85
            if '\t' in token:
                value = 3.0
        elif word in ('throw', 'raise'):
            value = (1.6 if word == 'throw' else 0.9) if code else 0.0
        elif word == 'break':
            value = 1.2 if code else -0.02
        elif word == 'continue':
            value = 1.2 if code else -0.05
        else:
            value = 0.5 if code else 0.0
    elif '=>' in s:
        value = 2.5 if line.rstrip().endswith(("'", '"')) else 1.1
    elif s in (':"', ":'", '":"', "':'"):
        value = 0.9
    elif s.endswith('.') and (')' in s or ']' in s):
        value = 0.95
        if s in (').', ')).', '].'):
            value = 0.3 if re.search(r'[=;{}]|\b(return|const|let)\b', recent[-150:]) else 0.05
        if '\n' in token:
            value = 0.0
    elif s == '.' and token.startswith(' '):
        value = 0.8 if not line.strip() and re.search(r'[)\]]\s*$', recent) else 0.05
    elif s == '::':
        value = 1.15 if re.search(r'\bstd$', line) else 0.06
    elif s in ('||', '??', '&&', '?:'):
        value = {'||': 0.15, '??': 0.7, '&&': 0.1, '?:': 1.0}[s]
    elif s.endswith('->'):
        value = 1.0 if line.rstrip().endswith(')') else 0.12
    return (doc, (before + token)[-400:]), value

programs.haiku:
"""layers.1.mlp.down_proj:1705, a "a value or body comes next" detector.

What it responds to (all measured on training text):
  * The colon that closes a quoted key in JSON or a Python/JS dict: `":` `':` `":"` `:"`.
    Mean activation about 2.
  * The colon after a bare key inside an object literal, `{ type: 'X', name: y }`, where the
    key starts an entry (after indentation, a space or a comma). Mean about 2.2. A key that
    follows a bare `{`, a quote or a `case` label gets 0, and a colon anywhere outside
    braces (prose, times, file paths, `print` labels) gets 0.
  * The keywords `return` and `throw` (about 2.5) and `break` (about 1). Each is the word
    right before its value or statement.
  * The arrow `=>` (about 1.7), which is followed by a body or value.
  * The ternary `?:` and the dot after a closed call, `().`, `").`, `'].`, which begin a
    chained method (about 1).
Everything else predicts 0. The program tracks open `{`, `(`, `[` brackets in its carry,
and resets them at each new document.
"""

READS = ()

QUOTED_KEY_COLONS = {'":', "':", '\\":', '":"', ':"', "':'"}
RETURN_WORDS = {"return", "throw"}
CHAIN_TOKENS = {"?:", "().", '").', "']."}


def step(carry, prefix, upstream):
    # Open brackets before this token, innermost last.
    stack = list(carry) if carry else []
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        stack = []

    tok = prefix.token_strings[-1]
    word = tok.strip()
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    prev2 = prefix.token_strings[-3] if len(prefix.token_strings) > 2 else ""

    if word in QUOTED_KEY_COLONS:
        value = 2.0
    elif word in RETURN_WORDS:
        value = 2.5
    elif word == "break":
        value = 1.0
    elif word == "=>":
        value = 1.7
    elif word in CHAIN_TOKENS:
        value = 1.0
    elif word == ":" and stack and stack[-1] == "{" and prev.strip().isidentifier():
        # A bare key inside an object literal: strong when it starts an entry.
        if prev2 in ("{", "'", '"'):
            value = 0.0
        elif prev2[:1] in " \t\n,":
            value = 2.2
        else:
            value = 1.0
    else:
        value = 0.0

    for ch in tok:
        if ch in "{([":
            stack.append(ch)
        elif ch in "})]" and stack:
            stack.pop()
    return tuple(stack), value

programs.sol:
"""A pulse before the document has acquired varied context.

Emit a token-shape-dependent value on the first token and its uninterrupted
repetitions, then zero.  ASCII words get a length/case approximation; control markers, whitespace,
numbers and punctuation have their own broad scales.
This captures the onset effect, not the full token-specific variation in it.
"""
import regex

READS = ()


def onset_value(text):
    word = text.strip()
    if text == '<|im_start|>':
        return 6.58
    if text == '<|endoftext|>':
        return 9.3
    if text.startswith('<|'):
        return 4.9
    if not word:
        if '\n' in text:
            return 0.1 if text == '\n' else 1.5
        if text == '\r':
            return 1.3
        return 3.6 + 2.0 * min(max(len(text) - 1, 0), 2)
    if word.isascii() and word.isdecimal():
        return 4.5 if int(word) % 2 == 0 else 2.6
    if word.isascii() and word.isalpha():
        if len(word) == 1 and word.islower():
            return 3.3 if text.startswith(' ') else 1.7
        return (4.04 + 0.39 * min(len(word), 12)
                + 2.17 * word.istitle() - 1.21 * word.isupper()
                - 0.25 * text.startswith(' '))
    if word.startswith('\\') and len(word) > 1:
        return 16.0 if word[1] in 'ntr\"\'' else 10.0
    if set(word) == {'#'}:
        return 5.8
    if word[0] in '([{':
        return 1.0
    if word[0] in ')]}':
        return 2.9
    if regex.search(r'\p{Script=Han}', word):
        return 4.9
    if regex.search(r'\p{Script=Cyrillic}|\p{Script=Arabic}', word):
        return 3.5
    if regex.search(r'\p{Script=Hiragana}', word):
        return 2.7
    if word.isalpha():
        return 4.5
    return 3.8


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_ids[-1]
    if carry is None or doc != carry[0]:
        value = onset_value(prefix.token_strings[-1])
        return (doc, token, value), value
    _, initial_token, value = carry
    if token != initial_token:
        initial_token, value = None, 0.0
    return (doc, initial_token, value), value

programs.haiku:
"""Document-start detector for layers.1.mlp.down_proj:1706.

What it does: the component fires on the first token of each document: the first token
of a packed row, or the token where the document id changes inside a row. A document's
first token sees no earlier text, and the component writes a strong push there. At every
other position it is near zero, so this program predicts 0 there.

How strong the push is depends on the word that opens the document:
  - English -ing / -ed verb forms (e.g. "validated", "Testing"): strongest, about 9;
  - a capitalised word with no leading space (e.g. "The", "New"): about 7.5;
  - any other word: about 5.5;
  - punctuation, digits, spaces, special tokens: weakest, about 3.5.
"""

READS = ()

ING_ED_VALUE = 9.0
CAPITAL_VALUE = 7.5
WORD_VALUE = 5.5
OTHER_VALUE = 3.5


def is_plain_word(text):
    return text.isascii() and text.isalpha()


def start_strength(token):
    """Activation predicted for a document-initial token, given its decoded text."""
    word = token.strip()
    if is_plain_word(word) and word.lower().endswith(("ing", "ed")) and len(word) > 4:
        return ING_ED_VALUE
    if is_plain_word(word) and word[:1].isupper() and not token.startswith(" "):
        return CAPITAL_VALUE
    if word.isalpha():
        return WORD_VALUE
    return OTHER_VALUE


def step(carry, prefix, upstream):
    t = prefix.position
    starts_document = t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]
    if not starts_document:
        return None, 0.0
    return None, start_strength(prefix.token_strings[-1])

programs.sol:
"""A partial approximation of sparse format and character-fragment responses.

Document starts get case-sensitive adjustments for The, I, whitespace,
module headers and block comments. PHP openers are negative; an annotation
immediately after /** is positive. Single-byte UTF-8 completions of flag
letters, braille, runes, mathematical capitals and some symbols are negative.
Japanese の, the thinking marker and nonbreaking spaces have small offsets.
Leading runs of carets and middle dots have separate negative responses.
Everything else is nearly zero: most token-specific background is unmodeled.
"""
import unicodedata

READS = ()
MODULE_HEADERS = frozenset({
    'import', 'from', 'use', 'include', 'require', 'package', 'namespace',
})


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail, age, only_marks = b'', b'', 0, True
    else:
        _, previous, tail, age, only_marks = carry
    raw = prefix.token_bytes[-1]
    text = prefix.token_strings[-1]
    joined = tail + raw
    value = -0.001

    if age == 0:
        if text == 'The':  # Capitalized English definite article.
            value = -0.308
        elif text == 'I':  # Capitalized first-person pronoun.
            value = -0.577
        elif raw == b'\t':
            value = 0.819
        elif raw == b'\n':
            value = -0.334
        elif raw.startswith(b'/*'):
            value = 0.85
        elif text.strip() in MODULE_HEADERS:
            value = 0.35

    if raw == b'php' and previous == b'<?':
        value = -1.16 if age == 1 else -0.25
    elif raw == b' @' and previous.rstrip().endswith(b'/**'):
        value = 1.2
    elif text == 'の':
        value = -0.11  # Japanese genitive/linking particle.
    elif text == '<think>':
        value = -0.15
    elif text == '\u00a0':
        value = -0.035

    if len(raw) == 1 and 0x80 <= raw[0] < 0xc0:
        char = joined.decode('utf-8', 'replace')[-1:]
        name = unicodedata.name(char, '')
        if name.startswith('REGIONAL INDICATOR SYMBOL'):
            value = -0.82
        elif name.startswith('BRAILLE PATTERN'):
            value = -0.7
        elif name.startswith('RUNIC LETTER'):
            value = -0.4
        elif name.startswith('MATHEMATICAL') and char.isupper():
            value = -0.3
        elif unicodedata.category(char) == 'So':
            # Upper-half final continuation after a lower-half encoding byte.
            upper_final = bool(raw[0] & 0x20)
            lower_previous = previous and not (previous[-1] & 0x20)
            value = -0.35 if upper_final and lower_previous else -0.04

    marks = bool(text) and set(text) <= {'^', '·'}
    if only_marks and marks:
        if set(text) == {'^'} and len(text) >= 4:
            value = -1.74
        elif set(text) == {'·'} and len(text) >= 2:
            value = -0.905
    carry = (doc, raw, joined[-12:], age + 1, only_marks and marks)
    return carry, value

"""A spelling detector, mainly for PC-like letter clusters.

Short PC abbreviations are positive. A C-initial fragment after a P-ending
fragment is also positive, whereas F- and S-initial continuations tend to be
negative. Capital P followed by 'fe'/'fer' is especially negative. Case,
separators and a few common initialisms adjust the strength. Minor rules cover
'Title:' just after an end marker, repeated middle dots, and a row-start offset.
These are spelling rules, not claims about the abbreviations' meanings.
"""
READS = ()


def predict(s, previous, first=False, before_previous=""):
    value = -0.20 if first else 0.0
    word = s.strip(' \t\n_./-')
    low = word.lower()
    if s and set(s) == {'·'} and len(s) > 1:
        return 1.05
    if s == ':' and previous == 'Title' and before_previous == '<|endoftext|>':
        return -5.27

    # Common PC-containing initialisms, including their use in identifiers.
    if low in ('rpc', 'grpc'):
        if s[0].isalpha():
            return 7.5
        return 6.0 if low == 'rpc' and s.startswith(' ') else 4.8
    if low == 'ipc':
        return 5.5
    if low == 'lpc':
        return 7.0
    if low in ('pc', 'pcs', 'pct', 'pci', 'pca', 'pcb', 'pcm'):
        value = 3.8 if s.startswith(' ') else 4.3
        if word == 'PCs':
            value = 2.3
        elif low == 'pcs':
            value = 3.4 if s.startswith(' ') else 4.5
        elif low in ('pca', 'pcb', 'pcm'):
            value = 0.8 if s.startswith(' ') else 3.0
        elif word == 'PCI':
            value = 1.5
        elif low != 'pc':
            value -= 0.5
        if s.startswith('_'):
            value *= 0.6
        if not s.startswith(' ') and previous:
            ending = previous[-1]
            if ending in 'RvV' or previous.lower().endswith('/r'):
                value += 2.4
            elif ending.isascii() and ending.isupper() and ending != 'B':
                value += 0.8
