    if low in ('npc', 'apc'):
        return 2.5
    if low in ('ppc', 'mpc', 'hpc', 'opc'):
        return 4.5
    if word in ('PVC', 'PLC', 'PCR', 'CPL'):
        return 1.6

    # The same letter-cluster preference also occurs in Cyrillic.
    if previous.endswith('П') and s in ('К', 'Ц'):
        return 5.5 if s == 'К' else 3.0
    if s == 'PA' and previous.endswith('C'):
        return 4.0
    if s == ' C' and previous == '.' and before_previous.strip() == 'P':
        return 5.1
    if s == 'C' and previous == '\n' and before_previous.strip() == 'P':
        return 3.7
    if s == ' C' and previous.strip() in ('P', 'P.'):
        return 7.5 if previous.strip() == 'P' else 5.1

    # A cluster may be split across tokens. Separators usually weaken it.
    p_end = previous.lower().endswith('p')
    if s == 'c' and previous.lower().endswith(('pr', 'pl')):
        return 2.3
    if p_end and s and not s[0].isspace():
