            return 6.8
        if s == '.com' and previous.lower().endswith('np'):
            return 1.0
        if s in ('-c', '-C'):
            return 1.8
        if s.startswith('c') or s.startswith('C'):
            if s == 'C':
                letters = previous.strip(' ._-/')
                if not letters.isupper():
                    return 0.2
                return 10.0 if letters.endswith(('IP', 'AP')) else 6.5
            if s == 'c':
                return 9.0 if previous.lower().endswith('ip') else 5.5
            if len(s) <= 3:
                if s.startswith(('ci', 'cs', 'CT')):
                    return 5.5
                if s.startswith(('ca', 'CL', 'CD')):
                    return 3.8
                if s.startswith('CH'):
                    return 4.7
                if s.islower() or s.isupper():
                    return 2.3
            return 0.3
        if s.lower().startswith('f') and 1 < len(s) <= 4:
            if s.startswith(('fl', 'FL')):
                return -2.6
            if s.lower().startswith('fe') and previous.strip() == 'P':
                return -5.5
            if s.lower().startswith('fd'):
                return -3.8
            return -1.3 if len(s) <= 3 or s.lower() == 'file' else -0.3
        if s == 'SPACE':
            return -3.0
        if s == 'Service':
            return -1.3
        if s.lower().startswith('s') and 1 < len(s) <= 4:
            return -2.0 if s.lower() == 'ss' else -1.0
        if len(s) <= 3 and s.isupper() and 'C' in s:
            return 1.7
        if s == 'V':
            return 2.0
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    previous = '' if first else carry[1]
    before_previous = '' if first else carry[2]
    s = prefix.token_strings[-1]
    return (document, s, previous), float(
        predict(s, previous, first, before_previous)
    )

