D_LETTERS = set("dDđĐдДδد")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    s = tok.strip()
    low = s.lower()
    if "d" not in low and not any(ch in D_LETTERS for ch in s):
        return None, 0.0
    if s in D_LETTERS:
        base = 1.8
    elif len(s) == 2:
        base = 1.0
    elif low.endswith("d"):
        base = 0.5
    else:
        base = 0.6
    glued = not tok.startswith(" ") and len(prefix.token_strings) > 1
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
