"""Lexical and phrase triggers for indefinite amounts and selection prompts.

The strongest ordinary-text responses are `a certain`, `which of the
following`, and Chinese 多少 ('how much/many'). Smaller rules cover blanks,
empty parentheses and a LaTeX array opening. A document-initial `Title:`
header and repeated middle-dot leaders have negative responses. Most
unmodelled text is zero; these rules do not reconstruct all of the
component's weaker or rare-character responses. Only a short byte suffix
of the current document is kept, resetting at document boundaries.
"""
import regex as re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history = b''
    else:
        history = carry[1]
    raw = prefix.token_bytes[-1]
    before = history.decode('utf-8', 'replace')
    token = raw.decode('utf-8', 'replace')
    after = history + raw
    word = token.strip()
    lower = before.lower()
    value = 0.0

    if word == 'certain':
        if re.search(r'\b[aA]$', before):
            value = 1.95
        elif re.search(r'\bun$', before):
            value = 1.0
        elif re.search(r'\bune$', before):
            value = 0.55
        else:
            value = 0.09
    elif word == 'following':
        if re.search(r'which (?:one of|of|among) the$', lower):
            value = 2.0
        elif re.search(r'\bof the$', lower):
            value = 0.45
        elif re.search(r'\bthe$', lower):
            value = 0.04
            if re.search(r'\b(consider|read|translate|find|evaluate) the$', lower):
                value = 0.55
        else:
            value = -0.04
    elif '多少' in word:
        value = 3.5 if word == '多少' else 2.45
        if word.endswith('钱'):
            value = 1.25
    elif word == '某':  # an unspecified person or thing
        value = 0.55
    elif word == '少' or (
        word == '\ufffd' and after.decode('utf-8', 'replace').endswith('少')
    ):  # 'few/little', including its split-byte spelling
        value = 0.8 if word == '\ufffd' else 0.28
        if re.search(r'[\p{Script=Hiragana}\p{Script=Katakana}]$', before):
            value = 0.8
    elif word and set(word) == {'_'}:
        run = len(before) - len(before.rstrip('_'))
        # Short answer blanks, not long signature/separator rules.
        if 2 <= run + len(word) <= 24:
            value = 0.3
            if run and len(word) >= 2:
                value = 1.0
    elif (word in (')', '）')
          and (token.startswith(' ') or before.endswith(' '))
          and before.rstrip().endswith(('(', '（'))):
        value = 0.85
    elif word == 'array' and before.endswith('begin{'):
        value = -1.0
    elif word == ':' and before == 'Title':
        value = -6.17
    elif word == '··':
        value = -1.165

    return (doc, after[-384:]), value

programs.haiku:
"""Quantity and unspecified-reference words, in the MLP of layer 1.

Component layers.1.mlp.down_proj:1710 is mostly silent. It fires on a few words
that introduce an unnamed or unspecified item: "a certain" (an unspecified X),
"of the following" (a list about to be named), and the Chinese "多少" (how much /
how many) and "某" (some / a certain). Where a document begins, with no context
yet, it leans positive for a lowercase word that continues a sentence and slightly
negative for blank or whitespace-only tokens. It is strongly negative on the
dot-leader filler "··" and on the colon of a "Title:" header that opens a
document after <|endoftext|>. Everywhere else it is near zero.
"""

READS = ()

CERTAIN_AFTER = {"a", "A"}
QUANTITY = {"多少": 3.2, "某": 0.6}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    prev2 = prefix.token_strings[-3] if len(prefix) > 2 else ""
    if tok == " certain" and prev.strip() in CERTAIN_AFTER:
        return carry, 2.3
    if tok == " following" and prev == " the" and prev2 == " of":
        return carry, 1.3
    if tok == ":" and prev == "Title" and prev2 == "<|endoftext|>":
        return carry, -6.2
    if tok == "··":
        return carry, -1.2
    if tok in QUANTITY:
        return carry, QUANTITY[tok]
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        if tok.startswith(" ") and tok[1:2].islower():
            return carry, 0.22
        if tok.strip() == "":
            return carry, -0.15
    return carry, 0.0

programs.sol:
"""Approximate a document-opening signal with token-dependent strength.

The opening token, and an uninterrupted repetition of it, get a signal.
After a different token, predict zero until the next document. Estimate the
opening strength from spacing, character/word classes, case, length, and
English word frequency. These broad rules omit fine token-specific variation.
"""
import regex
from wordfreq import zipf_frequency

READS = ()


def opening_strength(text):
    word = text.strip()
    length = len(word)
    leading_space = text.startswith(' ')

    if text.startswith('<|'):
        return 2.4                 # Chat/document boundary markers.
    if text.isspace():
        if '\n' in text or '\r' in text:
            return 14.6
        if '\t' in text:
            return 12.4
        return 5.8 if len(text) == 1 else 10.8
    if word.isdigit():
        return 16.1
    if word.replace('’', "'") in {
        "'s", "'re", "'ve", "'ll", "'d", "'m", "'t", "n't"
    }:
        return 4.0                # English contraction/possessive endings.

    if regex.fullmatch(r'\p{Script=Latin}+', word):
        frequency = zipf_frequency(word.lower(), 'en')
        if leading_space:
            if length == 1:
                return 9.4
            if length <= 3:
                return 4.5
            return 4.3 if word.islower() else 6.9
        if length == 1:
            return 14.1 if word.isupper() and frequency > 6.5 else 18.6
        if word in ('import', 'from', 'using', 'package'):
            return 2.1            # Dependency/module declaration keywords.
        if length >= 3 and frequency >= 6.2:
            return 5.6            # Very common English words.
        if word.isupper():
            return 13.9
        if length == 2:
            return 12.6
        if frequency < 2:
            return 7.3            # Rare strings, often word fragments.
        return 11.8

    if word and all(not char.isalnum() for char in word):
        if '\n' in text:
            return 13.4
        if all(char in '.,:;?!' for char in word):
            return 8.9
        return 11.3 if leading_space else 13.1
    if regex.search(r'\p{Script=Han}', word):
        return 9.9
    return 12.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, opening_strength(prefix.token_strings[-1]))
    elif token != carry[1]:
        carry = (doc, None, 0.0)
    return carry, carry[2]

programs.haiku:
"""Candidate 9: the first token of each document gets a value by what it looks like; else 0.

A document starts at the beginning of a row, and after each <|endoftext|>. Its value is high
for bare characters, digits and line breaks, middling for other words and symbols, and low for
common function words (space-led words, 'The', 'It', ...)."""
READS = ()
COMMON_WORDS = {"The", "It", "This", "They", "What", "How", "We", "In", "On", "Are", "Which",
                "Because", "Using", "Another", "Despite", "These", "There", "Welcome"}

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    n = len(prefix.token_ids)
    if not (n == 1 or prefix.token_strings[-2] == "<|endoftext|>"
            or prefix.document_ids[-1] != prefix.document_ids[-2]):
        return None, 0.0
    word = tok.strip()
    if tok.startswith("<|"):
        return None, 2.5
    if tok.startswith(" ") and word[:1].isalpha():
        return None, 3.0
    if word in COMMON_WORDS:
        return None, 3.0
    if word.isalnum() and len(word) <= 2:
        return None, 18.0
    if word.isdigit():
        return None, 17.0
    if word == "" or tok[:1] in "\r\n\t":
        return None, 14.0
    if not word[:1].isalnum():
        return None, 9.0
    return None, 12.0

