"""Detect short e+j spelling fragments, not the meanings of their words.

The strongest case is a j-piece immediately after a piece ending in e.
Short pieces containing ej, Cyrillic ей, and Cyrillic е followed by a
vowel or й also respond. Longer pieces weaken the signal. There is a
small one-piece continuation after ej. Japanese and Korean e+i spellings
and Japanese e+long-vowel fragments are weaker parallels. An initial
Title: header is a separate strong case.
All context is reset at a document boundary; other responses are left zero.
"""
from functools import lru_cache
import unicodedata

READS = ()


@lru_cache(maxsize=16384)
def latin_plain(text):
    result = []
    for ch in text.lower():
        if 'LATIN' in unicodedata.name(ch, ''):
            result.extend(c for c in unicodedata.normalize('NFD', ch)
                          if not unicodedata.combining(c))
        else:
            result.append(ch)
    return ''.join(result)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, position = '', 0
    if carry is not None and carry[0] == doc:
        previous, position = carry[1], carry[2] + 1
    token = latin_plain(prefix.token_strings[-1])
    short = token.strip()
    n = len(short)
    last = previous[-1:]
    value = 0.0

    if token.startswith('j') and last == 'e':
        if n <= 4:
            value = (0.0, 4.8, 3.3, 1.5, 0.2)[n]
    elif 'ej' in short and (n <= 3 or short.endswith('ej')):
        value = max(0.0, 7.4 - 1.6 * n)
    elif token == 'ей':
        if last in 'аеёиоуыэюяьй' and last:
            value = 0.6
        elif last in 'жшщчц' and last:
            value = 0.8
        else:
            value = 2.2
    elif 'ей' in token and not token.startswith(' ') and n <= 4:
        value = 0.9 if n == 3 else 0.1
        if token[0] in 'шщ':
            value = 0.2
    elif last in ('е', 'э') and token and n <= 4:
        initial = token[0]
        if initial in 'яї':
            value = 4.0 * 0.55 ** (n - 1)
        elif initial == 'е':
            value = 2.2 * 0.56 ** (n - 1)
        elif initial == 'й':
            value = 1.8 * 0.55 ** (n - 1)
        elif initial in 'юё':
            value = 1.1 * 0.55 ** (n - 1)
        elif initial == 'и':
            value = 0.5 * 0.4 ** (n - 1)
    elif previous.endswith('ej') and len(previous.strip()) <= 3:
        if token[:1].isalpha():
            value = 1.5 * 0.7 ** max(0, n - 1)

    # Kana whose vowel is e. The replacement glyph marks a split character.
    kana_e = ('えけげせぜてでねへべぺめれ'
              'エケゲセゼテデネヘベペメレ')
    if last and last in kana_e:
        if token == 'イ':
            value = 0.7
        elif token == 'ー�':
            value = 1.2
    if token == '이' and last:
        if unicodedata.normalize('NFD', last).endswith(('ᅦ', 'ᅢ')):
            value = 1.6
    if position == 0 and token == 'title':
        value = 0.88
    if position == 1 and previous == 'title' and token == ':':
        value = 9.6
    return (doc, token, position), value

"""Approximate this component with sparse phrase and spelling cues.

Negative cues: temperature units, oceans, ozone, zoo, existential
"there ... exist", and the botanical ending -aceae. Joins after z
have signed vowel-spelling cues, modulated by the new piece's length.
Otherwise predict near zero, with a small document-start default.
This captures coarse regularities, not fine token-specific variation.
"""
import re
import unicodedata

READS = ()


def activation(s, prev, recent, first):
    low = s.strip().lower()
    old = prev.strip().lower()
    tail = recent.lower()
    joined = tail + s.lower()
    n = len(low)
    if low in ('exist', 'exists'):
        existential = re.search(
            r'\bthere(?:\s+(?:must|can|should|does|not|also|therefore))?\s*$',
            tail)
        if existential:
            return -5.49 if low == 'exist' else -6.6
        return 0.29
    if low in ('ocean', 'oceans'):
        return -4.06
    if ('ocean' in joined[-25:] and 'ocean' not in tail[-25:]
            or low == '海洋'):
        return -4.06
    if low == 'ozone':
        return -5.3
    if (re.search(r'\bozon', joined) and not re.search(r'\bozon', tail)
            and not re.search(r'\bozon', s.lower())):
        return -12.0
    if low == 'zoo':
        return -2.79
    if s.strip() == 'pH':
        return -0.77
    if s.strip() == 'H' and old == 'p':
        return -2.93
    if low in ('°c', '°f'):
        return -2.08 if low.endswith('c') else -0.95
    if low == 'celsius':
        return -2.8
    if s.strip() in ('C', 'F', 'N', 'S', 'E', 'W'):
        degree = re.search(r'(?:\d\s*[°º˚•o�]+|\bdegrees?)\s*$', tail)
        if degree:
            return -4.74 if low == 'c' else -1.42
        if low in ('c', 'f'):
            return 0.15
    if low == 'ae' and tail.endswith('ace'):
        return -1.7
    if s and not s[0].isspace() and low.isalpha():
        # A single z or a vowel-z ending, not consonant clusters like -tz/-zz.
