                  (len(old) == 1 or old[-2] in 'aeiou'))
        if z_join:
            plain = ''.join(c for c in unicodedata.normalize('NFD', low)
                            if not unicodedata.combining(c))
            if plain.startswith('oo'):
                return -7.3 * 0.5 ** max(0, n - 2)
            if plain.startswith(('ai', 'ay')):
                return 3.5 if n == 3 else 0.65
            if plain.startswith(('ah', 'aa')):
                return -1.4 if n == 3 else -0.2
            if plain.startswith(('an', 'ar')):
                return -1.9 if n == 2 else -0.45
            if plain.startswith('i'):
                if len(plain) > 1 and plain[1] in 'nctd':
                    return 0.89
                return 0.24
            if plain.startswith('or'):
                return 0.93
            if plain.startswith(('on', 'oe')):
                return -3.0 if n == 2 else -1.5
            if plain.startswith('o'):
                return -0.6 if n <= 2 else -0.2
            if plain.startswith(('un', 'uc')):
                return -2.9 if n == 2 else -1.8 if n == 3 else 0.0
            if plain.startswith(('us', 'ou')):
                return 0.82
            if plain.startswith('u'):
                return -0.14
            if plain.startswith(('ee', 'eh')):
                return -1.44
        if old == 'з' and low.startswith('о'):
            return -1.67
    if first:
        return 0.19
    return -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    if first:
        prev, recent = '', ''
    else:
        _, prev, recent = carry
    value = activation(s, prev, recent, first)
    return (doc, s, (recent + s)[-60:]), value

programs.haiku:
"""Layer-1 MLP down_proj, component 1713.

What it does: a sparse, mostly negative detector for a handful of spelled-out
words and units, and near zero everywhere else. Its strongest responses are:
  * the Celsius/Fahrenheit unit letter written right after a degree sign
    ("incubated at 37 °C"), about -5 (C) and -2.7 (F);
  * the token "°C" as one piece, about -1.9;
  * "exist"/"exists" right after "there" or "therefore" ("there exists a"), about -6.5;
  * "ocean"/"oceans", about -3.6; and "zoo", "zone", "ozone" and kin, about -0.7;
  * other words that contain the letter pair "zo" or "oz" (zone-like spellings), about -0.2;
  * repeated middle-dot filler "··", about -0.4.
It is slightly positive for a bare "C" or "F" that is not after a degree sign, and
for the first token of each document (+0.2). Everything else is 0.
The values are the means observed on 3,000 training rows, rounded.
"""

READS = ()

DEGREE_MARKS = {"°", "º", "�", "degree", "degrees"}
THERE_WORDS = {"there", "therefore"}
OCEAN = {"ocean", "oceans"}
ZOO_ZONE = {"zoo", "zone", "ozone", "zona"}


def word_so_far(strings):
    """Letters of the word that ends at the newest token (its earlier pieces included)."""
    pieces = []
    for s in reversed(strings):
        core = s.strip()
        if not core or not core.isalpha():
            break
        pieces.append(core.lower())
        if s.startswith(" "):
            break
    return "".join(reversed(pieces))


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    tok = strings[-1].strip()
    prev = strings[-2].strip().lower() if len(strings) > 1 else ""
    docs = prefix.document_ids
    if len(docs) == 1 or docs[-1] != docs[-2]:
        return carry, 0.2  # first token of a document
    if tok == "C" and prev in DEGREE_MARKS:
        return carry, -5.0
    if tok == "F" and prev in DEGREE_MARKS:
        return carry, -2.7
    if tok in ("°C", "°F"):
        return carry, -1.9
    if tok in ("exist", "exists") and prev in THERE_WORDS:
        return carry, -6.5
    if tok in OCEAN:
        return carry, -3.6
    if tok in ZOO_ZONE:
        return carry, -0.7
    if tok == "··":
        return carry, -0.4
    if tok in ("C", "F"):
        return carry, 0.1
    word = word_so_far(strings)
    if "zo" in word or "oz" in word:
        return carry, -0.2
    return carry, 0.0

programs.sol:
"""Approximate a short start-of-context pulse, not the later background.

The second token has a large positive response after a single blank followed
by a digit, or after punctuation, line breaks, and very common English words.
The third token retains a response, especially for numbers after whitespace. English
word frequency separates very common grammatical context from other text.
Zero is used at the first token and after the third; lexical detail is omitted.
"""
from functools import lru_cache
from unicodedata import category
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=32768)
def frequency(text):
    word = text.strip()
    return zipf_frequency(word.lower(), 'en') if word.isalpha() else 0.0


def digit(text):
    return len(text) == 1 and '0' <= text <= '9'


def second(first, current):
    start, word = first.strip(), current.strip()
    number = digit(word)
    if first == ' ':
        if not word:
            return -0.13
        return 8.2 if number else 0.7
    if first == '\n':
        if number:
            return 5.6
        if word.isalpha():
            return 4.3
        return 1.7 if word else 3.0
    if first == '\t':
        return 1.7
    if first == '.':
        if number:
            return 6.1
        return 2.1 if word.isalpha() or current == ' ' else 0.5
    punctuation = bool(start) and all(category(c)[0] in 'PS' for c in start)
    if punctuation:
        if '\n' in first:
            return 0.7
        if start == ',':
            return 5.2 if number else 2.3
        if number:
            return 3.4 if len(start) == 1 else 0.5
        if start in ('(', '[', '{') and word.isalpha():
            return 2.7
        return 1.0 if len(start) == 1 else 0.25
    if '\n' in first:
        return 2.9
    commonness = frequency(first)
    if commonness <= 6.5:
        return 0.05
    if commonness <= 7.1:
        return 0.7
    if start.lower() == 'of':
        return 3.4
    return 2.0 if frequency(current) > 5.0 else 1.1


