"""Layer-1 MLP down_proj component 1718: fires on infinitive "to" in a modal or
obligation frame ("will have to", "might need to", "be able to"), and goes strongly
negative on word pieces spelling bee / bud / bear / bull (Ombudsman, honeybees, 蜂).

Plain-language rules, checked against the component's activations:
  * " to" after a need/obligation/ability word (need, have, able, sure, expected, required)
    is high (about 1.6 when a modal such as will/would/may/might/'ll/must/be is just
    before it, 0.5 otherwise). After a want/choose/prefer word it is weaker (0.6 or 0.3).
    After intention or aim words (try, plan, aim, going, way) it is slightly negative.
  * The current word, spelled out from its tokens so far, ends in bee/bees/bud/buds:
    -4. Ends in bear/bull/beau/belle: -2. The Chinese words 蜂 and 蜜蜂 also get -4.
  * " been" 0.3, " able" 0.45, " understood" 0.45; everything else 0.
"""
READS = ()

MODALS = {" be", " will", " would", " may", " might", " must", " should", " can", " could",
          " shall", "'ll", "’ll", " ll", " Will", " Would", " May", " Might", " Must", " Should",
          " Can"}
NEED_TO = {" need", " have", " able", " sure", " be", " expected", " required", " obliged",
           " obligated", " obvious", " likely", " possible", " happy", " supposed", " bound",
           " having", " Need", " got", " has"}
WANT_TO = {" want", " wish", " hope", " prefer", " choose", " decide", " wanting", " wants",
           " better", " order", " appear", " seem", " seemed", " expect", " learn", " free", " best"}
INTENT_TO = {" try", " tries", " tried", " trying", " plan", " plans", " aim", " aims", " tends",
             " continues", " continue", " going", " way", " ways", " about", " attempt", " efforts",
             " claims", " claim", " only", " just"}
BEE_WORDS = ("bee", "bees", "bud", "buds")        # bee, bud, Ombudsman, honeybees
BEAR_WORDS = ("bear", "bears", "bull", "bulls", "beau", "belle")
POSITIVE = {" been": 0.3, " able": 0.45, " understood": 0.45}

def current_word(toks, docs):
    """The word being spelled out by the tokens so far, lowercased."""
    word = toks[-1]
    i = len(toks) - 2
    while i >= 0 and docs[i] == docs[-1] and word[:1].isalpha():
        word = toks[i] + word
        if toks[i][:1].isspace():
            break
        i -= 1
    return word.strip().lower()

def step(carry, prefix, upstream):
    toks, docs = prefix.token_strings, prefix.document_ids
    cur, n = toks[-1], len(toks)
    word = current_word(toks, docs)
    if cur in ("蜂", "蜜蜂") or word.endswith(BEE_WORDS):
        return carry, -4.0
    if word.endswith(BEAR_WORDS):
        return carry, -2.0
    if cur == " to":
        def back(k):
            i = n - 1 - k
            if i < 0 or docs[i] != docs[-1]:
                return ""
            return toks[i]
        prev = back(1)
        modal = any(back(k) in MODALS for k in (2, 3))
        if prev in NEED_TO:
            return carry, 1.6 if modal else 0.5
        if prev in WANT_TO:
            return carry, 0.6 if modal else 0.3
        if prev in INTENT_TO:
            return carry, -0.2
        return carry, 0.0
    return carry, POSITIVE.get(cur, 0.0)

