"""A document-onset response, strongest for short Latin word fragments.

Estimate the opening token's gain from length, vowel proportion, capitalization,
and English word frequency. Common function words usually have a smaller gain.
Keep that response through an initial run of identical tokens; otherwise use zero.
This omits token-specific irregularities and the component's small later responses.
"""
import regex
from wordfreq import zipf_frequency

READS = ()
ARTICLES = {'a', 'an', 'the'}
PRONOUNS = set('i you he she it we they me him us them'.split())


def opening_gain(s):
    w = s.strip()
    if w == '<|im_start|>':
        return 5.4
    if w == '<|im_end|>':
        return 3.6
    if w == '<|endoftext|>':
        return -1.2
    if w.isascii() and w.isalpha():
        n = len(w)
        low = w.lower()
        spaced = s.startswith(' ')
        if n == 1:
            if low in ARTICLES:
                return -0.55
            if w == 'Q':  # A question label, rather than a letter fragment.
                return 0.18
            if spaced:
                return 5.5
            return 6.3 if low in 'aeiou' else 9.65
        if n >= 7:
            return 0.3
        frequency = zipf_frequency(low, 'en')
        if frequency > 6.8:
            return 4.05 if low in PRONOUNS else 0.16
        vowels = sum(c in 'aeiou' for c in low) / n
        if n <= 3:
            if spaced:
                return 4.0 if frequency <= 4.9 else 1.46
            if vowels > 0.6:
                return 2.06
            if frequency <= 4.4:
                return 7.85 if w.istitle() and frequency > 0.9 else 5.58
            return 7.96 if low in PRONOUNS else 4.23
        if frequency <= 3.8:
            return 4.73 if vowels <= 0.37 else 1.95
        return 1.13 if spaced else 2.33
    if not w:
        if s == '\t':
            return 7.85
        if s == '\r':
            return 7.0
        return 2.06 if s == '\n' else 0.0
    if regex.search(r'\p{Latin}', w):
        return -1.2 if w in {"'s", '’s'} else 3.48
    if any(c in ',.，。' for c in w):
        return -0.24
    if '\ufffd' in w:
        return 4.0
    if any(c.isalpha() for c in w):
        return 1.98
    return 1.07


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        value = opening_gain(prefix.token_strings[-1])
        return (doc, token, value), value
    if token == carry[1]:
        return carry, carry[2]
    return (doc, None, 0.0), 0.0

