"""Doc-initial word-fragment detector (draft 1)."""
READS = ()

FUNCTION_WORDS = set("""the a an of in on at to for and or but is are was were be been by with from
as that this these those it its he she they we you i me him her us them my your our their his not no
so if then than when where what which who how all any some each every more most other such only
also just about into over after before between under again there here up down out off can will would
should could may might must do does did have has had""".split())
PRONOUNS = set("i we you he she it me him us them they there".split())
# Average activation by kind of first token (fit on training documents).
FRAGMENT_LENGTH = {1: 8.0, 2: 6.0, 3: 5.0, 4: 3.3}
SPACED_WORD_LENGTH = {1: 5.5, 2: 4.0, 3: 3.0, 4: 2.0}


def first_token_value(text):
    if text == "<|im_start|>":
        return 5.4
    core = text.strip()
    if not (core.isascii() and core.isalpha()):
        return 1.0
    word = core.lower()
    n = len(core)
    if text.startswith(" "):
        if word in FUNCTION_WORDS:
            return 0.5
        return SPACED_WORD_LENGTH.get(n, 0.9)
    if word in PRONOUNS:
        return 7.0
    if word in FUNCTION_WORDS:
        return 0.0
    return FRAGMENT_LENGTH.get(n, 1.0)


def step(carry, prefix, upstream):
    """Activation is nonzero only on a document's first token, where it depends on that token."""
    t = prefix.position
    starts_doc = t == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]
    if not starts_doc:
        return None, 0.0
    return None, float(first_token_value(prefix.token_strings[-1]))

