"""Sparse lexical and spelling-boundary responses.

Negative events include Chinese acceptance/contact/union expressions, a few
Korean and Vietnamese counterparts, split j/h and sibilant spellings, and
initial Python 'def' or the colon of initial 'Title:'. Positive events include
double middle dots and the partial UTF-8 prefix shared by spaced 坂/坏/坐.
This is a collection of narrow triggers, not a general semantic classifier;
it leaves small, diffuse activations at zero. Document boundaries reset state.
"""

READS = ()


def response(s, previous, raw, prior_raw, initial_title, at_start):
    if s == ':' and initial_title:
        return -9.375
    if s == 'def' and at_start:
        return -3.4

    # Accepting, receiving, joining, and physical contact.
    if '接受' in s:
        return -4.5
    if s in ('联合', '聯合'):
        return -4.1
    if s == '接收':
        return -3.0
    if s.startswith(('接触', '接觸')):
        return -2.5
    if previous.endswith('接'):
        if s.startswith(('触', '觸')):
            return -3.5
        if s.startswith(('收', '受', '客')):
            return -2.5
    if previous.endswith(('闭', '閉')) and s == '合':
        return -2.7
    if previous.endswith(('触', '觸')) and s.startswith(('摸', '碰')):
        return -1.5
    if s in ('配合', '接近'):
        return -0.65
    if previous.strip() == '연' and s == '합':  # Korean: union
        return -3.0
    if previous.strip() == '교' and s == '체':  # Korean: replacement
        return -1.9
    if previous.strip() == 'tiếp' and s.strip() in ('xúc', 'cận'):
        return -3.0  # Vietnamese: contact / approach

    # Transliteration digraphs crossing token boundaries.
    if previous.lower().endswith('j') and s.startswith(('h', 'H')):
        if previous == ' J':
            return -4.3 if s[0] == 'h' or len(s) > 1 else -2.2
        return -1.8
    if previous.lower().endswith('ch'):
        if s.lower().startswith('ch'):
            return -2.5
        if previous.strip().lower() in ('ch', 'ach', 'ich', 'och'):
            if s in ('h', 'H'):
                return -5.0 if previous == ' Ch' else -1.5
            if s in ('u', 'us', 'im'):
                return -0.8
    if previous.lower().endswith(('k', 'z')) and s.startswith('hu'):
        return -1.7
    if previous.lower().endswith('gu') and s == 'zh':
        return -1.5
    if previous.endswith(('ж', 'ч')) and s == 'ь':
        return -2.0 if previous.endswith('ж') else -0.35
    if previous.endswith(('ж', 'ч', 'Ч')) and s.startswith('у'):
        return -1.2
    if previous == 'ю' and s == 'ж':
