        return -2.2  # Gurmukhi vowel sign AA
    if raw == b'\x9d' and joined.endswith('झ'):
        return -3.3  # Devanagari JHA
    if raw == b'\x9d' and prior_raw == b'\xc2':
        return -1.0  # C1 control character U+009D
    if prior_raw == b' \xe1' and raw == b'\x9b':
        return -1.6  # partial Runic character after a space
    if s == '··':
        return 0.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s, raw = prefix.token_strings[-1], prefix.token_bytes[-1]
